programs.sol:
"""Recognize 'sense', its inflections, and split sens-/ense spellings.

'Sense' gives a large negative response. The idiom 'make sense' weakens
it; 'in the sense' is intermediate. A few related stems have smaller
responses. Split spellings are recognized across adjacent tokens, but
not across documents. There is a smaller echo on the following 'of'.
"""
import re

READS = ()
MAKE = {'make', 'makes', 'made', 'making'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, before, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    tail = before.lower()
    value = 0.0

    if lower == 'sense':
        words = re.findall(r'[a-z]+', tail)
        distance = next((i for i, w in enumerate(reversed(words[-3:]))
                         if w in MAKE), None)
        if distance is not None:
            value = -1.3 - 0.9 * distance
            if word[0].isupper():
                value -= 0.8
        elif word[0].isupper():
            value = -9.0
        elif 'in' in words[-4:]:
            value = -3.4
        elif words and words[-1] == 'common':
            value = -7.5
        else:
            value = -5.9
    elif lower in {'sensing', 'sensed'}:
        value = -5.7
    elif lower == 'senses':
        value = -1.8
    elif lower == 'sens':
        value = -1.5
    elif lower == 'nonsense':
        value = -1.7
    elif lower == 'consensus':
        value = -0.8
    elif not token[:1].isspace():
        # Token boundaries inside the sens- family and -ense suffix.
        if lower.startswith('ens') and tail.endswith('s'):
            if lower == 'ense':
                value = -12.0
            elif lower == 'enso':
                value = -4.5
            elif lower == 'enses':
                value = -6.5
            elif lower == 'ens':
                if tail.endswith('nons'):
                    value = -6.2
                elif re.search(r'\bs$', tail):
                    value = -3.2
                else:
                    value = -0.5
            elif lower.startswith('ensor'):
                value = -2.7
        elif lower in {'se', 'sis'} and tail.endswith('en'):
            value = -4.4
        elif lower == 'so' and tail.endswith('sen'):
            value = -4.4
        elif lower == 'é' and tail.endswith('cens'):
            value = -3.0
        elif lower == 'onsense' and tail.endswith('n'):
            value = -5.2
        elif token == 'ス' and before.endswith('セン'):
            value = -4.2
    if lower == 'of' and previous < -3.0:
        value = 0.17 * previous

    return (doc, (before + token)[-100:], value), value

"""A partial detector for numerical descriptions and unit conversions.

The largest predictions are for spoon/ton units, density notation, and
"to" joining converted quantities. Smaller rules cover equality, number
properties, mathematical relations, and a few question/heading cues.
Most other tokens get a near-zero background. A short trailing text
buffer supplies context and is cleared at document boundaries.
"""
import re

READS = ()
SPOONS = {'teaspoon', 'teaspoons', 'tablespoon', 'tablespoons', 'tsp', 'tbsp'}
MASS = {'ounce', 'ounces', 'pound', 'pounds', 'stone', 'stones', 'oz', 'lb'}
BASES = {'binary', 'decimal', 'hexadecimal', 'octal'}
CONVERT = {'convert', 'converts', 'converted', 'converting', 'conversion',
           'conversions', 'converter', 'converters'}
FACTOR = {'divisor', 'divisors', 'divisible', 'factorization',
          'factorisation', 'primality'}
UNIT = (
    r'(?:tsp|tbsp|tn|oz|lbs?|cm|mm|kg|ml|ft|yd|cf|mmbtu|'
    r'teaspoons?|tablespoons?|stones?|ounces?|pounds?|grams?|'
    r'(?:mega|kilo|milli|centi|deci|micro)?lit(?:er|re)s?|'
    r'(?:kilo|centi|milli|mega|deci)?met(?:er|re)s?|'
    r'gallons?|quarts?|pints?|cups?|inches|inch|feet|foot|yards?|miles?)'
)
UNIT_END = re.compile(r'\b' + UNIT + r'(?:[²³]|\^\d)?\s*$', re.I)
UNIT_WORD = re.compile(r'\b' + UNIT + r'\b', re.I)


def unit_end(text):
    return bool(UNIT_END.search(text) or
                re.search(r'/(?:m|in)(?:[²³]|\^\d)?\s*$', text))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = (old + token)[-180:]
    match = re.search(r'[A-Za-z]+$', text)
    word = match.group().lower() if match and token[-1:].isalpha() else ''
    before = text[:-len(word)] if word else old
    last = re.search(r'([A-Za-z]+)\s*$', before)
    last = last.group(1).lower() if last else ''
    unit = unit_end(before)
    converting = bool(re.search(r'\b(?:convert|convers)\w*', before, re.I))
    unit_topic = len(UNIT_WORD.findall(before)) >= 2
    compound = unit and ('/' in before[-20:] or
                         bool(re.search(r'[²³]|\^3', before[-8:])))
    value = -0.003
    if token.strip().isdigit():
        value -= 0.01
    if '{' in token and '\\' in token:
        value -= 0.11
    if token and set(token) <= {'·'} and old.endswith('··'):
        value += 1.32
    if (not old or old.endswith('<|endoftext|>')) and len(token) == 1:
        if token.isascii() and token.isupper():
            value += 0.47

    if word in SPOONS:
        technical = ('metric' in before[-15:].lower() or
                     last in {'us', 'uk'} or
                     (converting and unit_topic))
        value += 2.5 if technical else (1.0 if word in {'tsp', 'tbsp'} else 0.2)
    if word in MASS:
        value += 0.24
    if token.strip() == 'tn':
        value += 1.8
    if word in {'troy', 'dwt'}:
        value += 1.07
    if re.search(r'/(?:cm|mm)$', token):
        value += 0.82
    if token == '³' and unit_end(old):
        value += 0.5
    if word in CONVERT:
        value += 0.37 + 0.22 * token.strip()[:1].isupper()
        value += 0.6 * unit_topic
    if word in {'equal', 'equals', 'equivalent'}:
        value += 0.14 + 0.42 * (converting or unit_topic)
    if word in BASES:
        value += 0.08
    if word in FACTOR:
        value += 0.16
    if word in {'div', 'divisor', 'divisors'} and last == 'common':
        value += 0.67
    if word in {'fraction', 'fractions', 'percentage', 'percentages'}:
        value += 0.11
    if word in {'number', 'numbers'}:
        value += 0.08 + 0.18 * (last == 'prime')
    if word in {'weigh', 'weighs', 'weight'}:
        value += 0.08 + 0.8 * (last == 'molecular')

    if word == 'to':
        if compound:
            value += 3.6
        elif unit and converting:
            value += 3.0
        elif converting or last in BASES:
            value += 0.2
        if last in {'equal', 'equivalent', 'congruent', 'adjacent', 'rounded'}:
            value += 0.32
    if word == 'per':
        value += 1.3 if unit else 0.08
    if token.strip() == '=' and (unit or converting):
        value += 0.51
    if word in {'in', 'from'} and (unit or converting):
        value += 0.09
    if word == 'of' and last in {'coordinates', 'unit', 'factors', 'divisors'}:
        value += 0.6
    if word in {'formula', 'table', 'result'} and converting:
        value += 0.22
    if word in {'yes', 'no'} and re.search(r'\?\s*$', before):
        value += 0.8
    if word == 'links' and last == 'external':
        value += 0.7
    if '?' in token and '\n' in token and (unit or converting):
        value += 0.27
    if token.isspace() and '\n' in token and compound:
        value += 0.73
    return (doc, text), float(value)

"""Sparse syntax-marker responses, approximated with readable text rules.

Positive pulses mark comments, object keys, declarations, documentation tags,
and first-list-item punctuation. Line position and nearby syntax distinguish
these from ordinary prose. Long unfinished paragraphs followed by a heading
get a stronger heading response. Beginning-of-document Title: labels and runs
of middle dots have negative rules. Most tokens predict zero.

These are approximate syntax cues, not a parser or a token-identity model.
Only 300 recent characters are retained; state resets between documents.
"""
import re

READS = ()
DECLARATIONS = {'const', 'let', 'var', 'auto', 'final', 'class'}
TYPES = {'int', 'float', 'double', 'bool', 'boolean', 'char', 'string', 'String'}
MODIFIER = r'(?:public|private|protected|static|export|abstract|final)'


def activation(token, recent, position):
    mark = token.strip(' \t')
    if not mark or '\n' in mark or '\r' in mark:
        return 0.0
    # Also recognize code embedded in escaped strings and numbered listings.
    before = recent.replace('\\n', '\n').replace('\\r', '\r')
    before = before.replace('\\t', '\t')
    line = re.sub(r'^\s*\d+\t', '', before.rsplit('\n', 1)[-1])
    start = not line.strip(' \t+-')
    modified = bool(re.search(r'\b' + MODIFIER + r'(?:\s+' + MODIFIER + r')*$', line))

    # Key/value boundaries: first keys of objects tend to be stronger.
    if mark.lstrip('\\') == '":':
        first = re.search(r'{\s*\\*"[\w$-]*$', before)
        return 1.35 if first else 0.93
    if mark.lstrip('\\') == "':":
        return 0.0 if re.search(r'\b(?:case|elif|if)\s', line) else 0.8
    if mark == ':':
        if recent == 'Title' and position == 1:
            return -3.75
        field = re.search(r'(?:[{,]\s*|^\s*)[\w$]+$', line)
        function_header = re.search(r'\b(?:fn|def|function)\b', line.rsplit('{', 1)[-1])
        if field and '{' in before and not function_header:
            return 0.45 if re.search(r'\b(?:struct|interface)\b', before) else 0.88

    # Comment openings, including a few common documentation conventions.
    comments = {'//', '///', '//#', '/*', '/**', '#'}
    if mark in comments and position == 0:
        return -0.3
    if mark in {'/*', '/**'}:
        return 0.35
    if mark == '///':
        return 0.33
    if mark in {'//', '//#'}:
        return 1.0 if token.startswith(' ') else 0.75
    if mark.endswith('//') and mark.startswith((';', ')', '}')):
        return 1.0
    if mark == '#':
        if start:
            return 0.72
        quoted = any(len(re.findall(r'(?<!\\)' + q, line)) % 2 for q in ('"', "'"))
        code = (re.search(r'[=;]|[)\]}]\s*$', line)
                or re.match(r'\s*(?:return|continue|break|pass|import|if|else|'
                            r'elif|class|for)\b', line))
        comment = line.lstrip().startswith(('*', '//', '#'))
        if token.startswith(' ') and code and not quoted and not comment:
            return 1.25
    if mark == '--' and start:
        return 0.75
    if mark == ';' and re.search(r'\s{3,}$', line) and line.strip():
        return 1.4  # Assembly comment after an instruction.
    if mark == '%' and re.search(r'\s{2,}$', line) and '=' in line:
        return 1.65  # MATLAB-style inline comment.
    if mark == 'param' and before.endswith(('@', '\\', ':', '<', '</')):
        return 0.92

    # First item markers, rather than arbitrary decimal points or parentheses.
    if mark in {'.', ')', '.)'} and re.fullmatch(r'\s*1', line):
        return 0.82 if mark == '.' else 0.33
    if mark in {')', '.)'} and re.search(r'(?:^|[\s(])1$', before):
        return 0.33
    if mark == ')' and re.search(r'(?:^|[\s(])(?:a|A|i|I)$', before):
        return 0.4
    if mark == '-' and start:
        return 0.1
    if mark in {'##', '###', '####'} and start:
        paragraph = before.rstrip().rsplit('\n', 1)[-1]
        unfinished = len(paragraph) > 120 and paragraph[-1] not in '.:?!]`>*'
        return 1.9 if mark == '###' and unfinished else 0.04
    if len(mark) >= 2 and set(mark) == {'·'} and recent.endswith('·'):
        return -0.72
    if mark == '=>':
        return 0.87 if before.rstrip().endswith(('"', "'")) else 0.065

    # Declaration words matter at statement starts, not in running prose.
    if mark in DECLARATIONS:
        if mark == 'class':
            return 1.0 if modified else 0.65 if start else 0.0
        if mark == 'final' and modified:
            return 0.33
        if start:
            return 0.97 if token[:1].isspace() else 0.7
        if mark == 'let' and re.search(r'\bif$', line):
            return 0.38
    if mark in TYPES and start:
        return 0.28
    return 0.0


def step(carry, prefix, upstream):
    document = int(prefix.document_ids[-1])
    if carry is None or carry[0] != document:
        recent, position = '', 0
    else:
        _, recent, position = carry
    token = prefix.token_strings[-1]
    value = activation(token, recent, position)
    return (document, (recent + token)[-300:], position + 1), value

programs.haiku:
"""layers.1.mlp.down_proj:3139 - "key colon in an object literal" and code-syntax detector.

What it does, in plain terms. The component fires on punctuation and keywords that
open an item inside source code, mostly in JavaScript/TypeScript/JSON-style object
literals:
  * the colon that follows a key inside `{ ... }`, e.g. `{ id: 1, name: "x" }` or
    `{"name": "bash"}` (strongest: the quoted form `":` about 1.2, plain `:` about 0.85);
  * comment openers: `//` anywhere in code (about 0.9), `#` at the start of a line (about 0.75);
  * declaration words in code (let, const, var, param, class, =>), about 0.8 inside braces, 0.4 outside.
It stays near zero on prose, on the colons of type annotations (`let x: T`) and on
CSS-style declarations (a `;` inside the brace), and on most other tokens.

How it works. We track which bracket is innermost (`{`, `(`, `[`) by counting brackets in
the text so far, and whether a `;` has appeared since that bracket opened. Each token is
then scored by the rules above. Reset at each new document in a packed row.
"""
READS = ()

QUOTED_KEY_COLONS = {'":', "':", '\\":'}
SLASH_COMMENTS = {"//", " //", "///", " ///"}
HASH_COMMENTS = {"#", " #", "##"}
DECLS = {"let", " let", "const", " const", "var", " var", "param", " param",
         "class", " class", "\tvar", "\tconst", "\tclass", " =>"}
# Words after which a colon is a type or statement, not an object key.
NOT_KEY_BEFORE = {"let", " let", "const", " const", "var", " var", ";", ":", "."}


def _is_word(s):
    return s.strip().isidentifier()


def step(carry, prefix, upstream):
    # carry: the open brackets, each as [character, has a ';' appeared since it opened]
    if carry is None or prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        stack = []
    else:
        stack = carry
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    before = prefix.token_strings[-3] if prefix.position > 1 else ""
    # Inside an object literal: the innermost open bracket is `{` with no ';' since.
    in_object = bool(stack) and stack[-1][0] == "{" and not stack[-1][1]

    value = 0.0
    if tok in QUOTED_KEY_COLONS or tok == ":":
        if in_object and _is_word(prev) and before not in NOT_KEY_BEFORE:
            value = 1.15 if tok in QUOTED_KEY_COLONS else 0.85  # a key colon
        elif tok in QUOTED_KEY_COLONS:
            value = 0.45  # a quoted key colon outside braces (JSON inside a string)
    elif tok in SLASH_COMMENTS:
        value = 0.9
    elif tok in HASH_COMMENTS:
        starts_line = prev == "" or "\n" in prev or prev.strip() == ""
        value = 0.75 if starts_line else 0.2
    elif tok in DECLS:
        value = 0.8 if in_object else 0.4

    for ch in tok:
        if ch in "({[":
            stack.append([ch, False])
        elif ch in ")}]" and stack:
            stack.pop()
        elif ch == ";" and stack:
            stack[-1][1] = True
    return stack, value

programs.sol:
"""Approximate selected local idioms, chiefly Go assignment expressions.

Assignment to append gives the largest response; Go allocation, module
loading and repeated Go test headers give smaller ones. Other rules cover
stock conditional/reference phrases and a few literal formula/document
patterns. The first token has a negative offset; other unmatched tokens
stay near zero. State tracks document position, the previous token, a short
text suffix and the test-header count; it resets at document boundaries.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail, position, runs = '', '', 0, 0
    else:
        _, previous, tail, position, runs = carry
    prev, word = previous.strip(), token.strip()
    value = -0.25 if position == 0 else -0.003

    # Assignment values: Go built-ins, JavaScript imports, SQL/Excel syntax.
    if prev in {'=', ':='}:
        if token == ' append':
            value = 4.4 if prev == ':=' else 8.6
        elif token == ' make':
            value = 2.5 if prev == ':=' else 1.1
        elif token == ' require':
            value = 1.6
        elif word == '@@':
            value = 1.6  # SQL system-variable reference.
        elif word == 'IF':
            value = 1.4  # Excel conditional-function prefix.
    if prev == '===' and token == ' RUN':
        value = (0.8, 1.2, 1.4)[min(runs, 2)]
        runs += 1
    if token == '"fmt' and previous.isspace():
        value = -2.2  # Go import list's formatted-I/O package.

    # Stock conditional phrases and references to related material.
    if prev.lower() == 'if' and word in {'so', 'applicable'}:
        value = 1.3 if word == 'so' else 1.6
    elif prev.lower() == 'when' and word == 'appropriate':
        value = 1.5
    if prev.lower() in {'follow', 'check'} and word == 'these':
        value = -1.7
    elif prev.lower() == 'similar' and word in {'words', 'topics'}:
        value = 1.0
    elif prev.lower() == 'see' and word == 'all':
        value = 1.4
    if previous == '是' and token in {'的', '啊'}:
        value = 4.8 if token == '的' else 3.5  # Chinese affirmative phrases.

    # Literal formula and document-template continuations.
    if token == 'O' and tail.endswith('C(='):
        value = 4.5  # Carbonyl oxygen in C(=O.
    elif token == ' O' and prev == '+':
        value = 1.1  # Adding a big-O remainder term.
    if previous == 'This' and token == ' preview':
        value = -0.75
    if tail.endswith('preview shows') and word in {'page', 'pages'}:
        value = -3.4
    if position == 1 and previous == 'Title' and token == ':':
        value = -5.36

    return (doc, token, (tail + token)[-24:], position + 1, runs), value

programs.haiku:
"""Sketch v4 of layers.1.mlp.down_proj:3140, a sparse detector.

The component is mostly quiet, with a few sharp responses, almost all in short fixed
phrases. Predicted activation (its value in the residual stream's units):
  - first token of a document: a small negative value (about -0.3 for a word, -0.1 otherwise);
  - a function name right after an assignment: `x = append` 8, `x := make` 2.5,
    `x = make` 1, `x = require` 1.6 (the name that starts a call);
  - `=== RUN` (Go test logs): 1.3;
  - the affirmative particle after 是 (是的 / 是啊, "yes, indeed"): 4.5;
  - `If so`, `if applicable`, `When appropriate`: 1.5.
Everything else predicts 0.
"""
READS = ()

CONDITIONAL_WORDS = {"If", "if", "When", "when"}
CONDITIONAL_ENDINGS = {"so", "applicable", "appropriate"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = prefix.position
    cur = s[t].strip()
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, -0.3 if cur[:1].isalpha() else -0.1
    prev = s[t - 1].strip()
    if prev == "===" and cur == "RUN":
        return None, 1.3
    if prev == "=" and cur == "append":
        return None, 8.0
    if prev == ":=" and cur == "make":
        return None, 2.5
    if prev == "=" and cur == "make":
        return None, 1.0
    if prev == "=" and cur == "require":
        return None, 1.6
    if prev == "是" and cur in ("的", "啊"):
        return None, 4.5
    if prev in CONDITIONAL_WORDS and cur in CONDITIONAL_ENDINGS:
        return None, 1.5
    return None, 0.0

programs.sol:
"""A spelling-fragment approximation to a negative 'it' response.

Transliterate tokens, then look for 'it', 'yt', or an i/y--t token boundary.
Responses are strongest inside words and on short continuations of 'it'.
A preceding vowel, longer pieces, and capitals weaken the interior response;
rare English spellings strengthen it slightly. Only the previous token is
remembered, and that memory is cleared at document boundaries.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
VOWELS = 'aeiouy'


@lru_cache(maxsize=32768)
def spelling(token):
    a = anyascii(token).lower().strip()
    rare = 'it' in a and zipf_frequency(a, 'en') < 3.5
    return a, rare


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    a, rare = spelling(token)
    b, _ = spelling(previous)
    continuation = (bool(token) and bool(previous)
                    and token[0].isalpha() and previous[-1].isalpha())
    n = len(a)
    delayed = continuation and b.endswith('it')
    value = 0.0002

    if delayed:
        if n <= 2:
            value += -1.60 + 0.68 * previous[0].isspace()
        else:
            value += -0.37 - 0.45 * (len(b) <= 2)
    elif a.startswith('it'):
        if continuation:
            value += -0.83
            value += 0.82 * bool(b and b[-1] in VOWELS)
            value += 0.57 * (n > 4)
            value -= 0.19 * (rare and n > 2)
            value += 0.22 * token.lstrip()[:1].isupper()
        else:
            value += -0.065 - 0.06 * rare
    elif continuation and b.endswith(('i', 'y')) and a.startswith('t'):
        if n == 1:
            value -= 1.87
        elif n <= 3 and len(b) <= 2:
            value -= 0.85
        else:
            value -= 0.23
    elif a.endswith('it'):
        value += -0.084 - 0.255 * rare
    elif 'it' in a:
        value -= 0.051

    if not delayed and 'it' not in a and continuation and 'it' in b:
        value -= 0.098
    if 'yt' in a and a.endswith('t'):
        value -= 0.43
    return (doc, token), value

"""A short-range bracketed-expression syntax signal.

Track unmatched round, square and inline curly brackets. Predict positive
responses for operators, separators, and closing quotation marks near those
openers; LaTeX right-delimiter commands also respond positively. Code-block
braces after parenthesized expressions have a negative
response, as do nested opening parentheses and backticks more weakly.
Delimiter influence fades with token distance; documents reset it. Fullwidth
punctuation and backslash-escaped quotes are normalized before applying rules.
"""
import math
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, {c: [] for c in '([{'}, '', '')
    _, pos, stacks, prev, quote = carry
    # Represented code often backslash-escapes its quotation marks.
    s = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    s = re.sub(r"\\+([\"'])", r'\1', s)
    t = s.lstrip(' \t')
    strength = []
    for c in '([{':
        age = pos - stacks[c][-1] if stacks[c] else 1000
        strength.append(math.exp(-age / 7.0))
    round_, square, curly = strength
    nearby = max(strength)
    value = 0.0
    if re.fullmatch(r"[\"']+:[\"']*", t):
        value = 0.15 + 2.8 * nearby
    elif t == ':' and not quote:
        value = 2.0 * nearby
    elif t in ('+', '-', '−', '+\\', '-\\'):
        if prev.strip() not in ('(', '[', '{', '=', ',', ':'):
            value = (2.15 if t.startswith('+') else 1.7) * nearby
    elif t in ('*', '/', '^', '&', '|', ';'):
        weights = {'*': 1.4, '/': 1.0, '^': 0.7,
                   '&': 0.6, '|': 1.7, ';': 1.2}
        value = weights[t] * nearby
    elif t == '=>':
        value = 2.8 * nearby
    elif t.startswith('=') and not t.startswith('=='):
        value = 1.1 * nearby
    elif t in ('\",', "',"):
        value = 1.6 * max(round_, square, curly * 0.4)
    elif t == ',':
        value = 0.55 * max(square, curly)
    elif t in ('"', "'") and quote == t:
        value = max(1.7 * round_, 3.2 * square, curly)
    elif re.search(r'\{[ \t]*\r?\n$', t):
