        if prev.rstrip().endswith((')', '=>')) or ')' in t:
            value = -1.5 * math.exp(-age / 30.0)
        if prev.rstrip().endswith('))'):
            value -= 1.0
        elif prev.rstrip().endswith('=>'):
            value -= 0.5
    elif t == 'right' and prev.endswith('\\'):
        value = 0.8 + 0.5 * nearby
    elif t.startswith('('):
        value = -0.04 - 0.35 * nearby
    elif t.startswith('`'):
        value = -0.05

    for i, c in enumerate(s):
        if c == '\n':
            quote = ''
        if c in ('"', "'"):
            previous = s[i-1] if i else prev[-1:]
            if quote == c:
                quote = ''
            elif not quote and not previous.isalpha():
                quote = c
