import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        count, opening, previous = 0, token, ''
        brackets, line, frontmatter = [], '', token == '---\n'
    else:
        _, count, opening, previous, brackets, line, frontmatter = carry

    value = 0.0
    if count == 0:
        if token == '<!':
            value = 2.96
        elif token == '/*':
            value = 0.40
        elif token == '/*\n':
            value = 0.073
        elif token == 'Title':
            value = -0.835
        elif frontmatter:
            value = -0.38
    elif count == 1:
        if previous == '/*\n' and token == ' *':
            value = 0.835
        elif previous == '/*\r\n' and token == ' *':
            value = 0.686
        elif previous == 'Title' and token == ':':
            value = 3.42
    elif count == 2 and opening == '/*' and previous == '\n':
        if token == ' *':
            value = 0.837

    if frontmatter and token == ':' and line.strip().isidentifier():
        key = line.strip()
        if key == 'title':
            value = -1.17
        elif key == 'description':
            value = -0.85
        else:
