        if len(token.strip()) >= 6 and set(token.strip()) == {':'}:
            value = -1.05

    if token == ',':
        number = previous.strip().isdigit()
        value = 0.04 if number else 0.005
        if brackets:
            kind, position = brackets[-1]
            age = count - position
            if kind == '[':
                strength, decay = (0.58, 8) if number else (0.29, 5)
            elif kind == '{':
                strength, decay = (0.57, 5) if number else (0.27, 3)
            else:
                strength, decay = (0.18, 5) if number else (0.0, 1)
            value -= strength * math.exp(-age / decay)

