"""Layer-1 MLP down_proj component 3146: a spelled-out number detector.

It goes negative inside spelled-out number words, the way the model reads a number
word that is still being spelled out. Strongest on a later piece of a word the
tokenizer splits into several tokens, when the word is a tens, teen or -eth number
("Fort|y", "Six|ty", "fif|teen", "thirti|eth", "nin|ety", "fift|ies"): about -6. Weaker
on other later pieces ("fif|th", "tw|elve"), on pieces that begin a number word
("thirt", "fift") and on whole tens and teen words ("twenty", "fifteen"): -1 to -4.
Other whole number words ("one", "five") are barely negative. Number words in
French, German, Spanish, Italian and Russian ("deux", "zwei", "cinco", "два") are
about -1, and decade plurals ("1990s") about -0.5. Everything else is predicted as 0.
"""
import re

import inflect

READS = ()

_ENGINE = inflect.engine()
TENS = {"twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"}
FOREIGN = set(
    "deux trois quatre cinq sept neuf dix vingt zwei drei vier fünf sieben neun "
    "zehn zwanzig dos tres cuatro cinco siete nueve diez veinte due tre quattro "
    "sette nove dieci venti два три четыре пять семь девять десять двадцать".split()
)


def _english(numbers, ordinal):
    out = set()
    for n in numbers:
        text = _ENGINE.number_to_words(_ENGINE.ordinal(n) if ordinal else n)
        out.update(w for w in re.split(r"[\s-]+", text.lower()) if w.isalpha())
    return out


NUMBER_WORDS = _english(range(1, 1000), False) | _english(range(1, 1000), True)
NUMBER_WORDS -= {"and", "zero"}
NUMBER_WORDS |= {w + "s" for w in NUMBER_WORDS} | {w[:-1] + "ies" for w in TENS}
TEENS = {"thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"}
TENS_WORDS = TENS | TEENS | {w[:-1] + "ies" for w in TENS}
PARTIAL_WORDS = {w[:k] for w in NUMBER_WORDS for k in range(3, len(w))}
VALUES = {
    "tens, teen or -eth piece": -6.0,
    "later piece": -3.5,
    "partial number word": -1.3,
    "whole tens or teen word": -2.6,
    "whole number word": -0.1,
    "foreign number word": -1.0,
    "decade plural": -0.5,
}


def category(prefix):
    """What the current token is within a spelled-out number, or None."""
    doc = prefix.document_ids[-1]
    parts = []  # trailing letters of the last few tokens of this document, oldest first
    for i in range(len(prefix.token_ids) - 1, max(-1, len(prefix.token_ids) - 4), -1):
        if prefix.document_ids[i] != doc:
            break
        tok = prefix.token_strings[i]
        letters = re.search(r"[A-Za-z]*$", tok).group(0)
        parts.insert(0, letters)
        if letters != tok:  # a space or punctuation before these letters: a word boundary
            break
    cur = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if cur in ("s", "es") and re.search(r"\d$", previous):
        return "decade plural"  # "1990s"
    if not parts[-1]:
        return None
    word = "".join(parts).lower()
    # the word began in an earlier token
    inside = len(parts) > 1 and parts[-2] != "" and cur[:1].isalpha()
    if word in NUMBER_WORDS:
        if inside:
            if re.search(r"(ty|ties|teen|teenth|teens|ieth|eth)$", word):
                return "tens, teen or -eth piece"
            return "later piece"
        return "whole tens or teen word" if word in TENS_WORDS else "whole number word"
    if inside and word in PARTIAL_WORDS:
        return "partial number word"
    if word in FOREIGN:
        return "foreign number word"
    return None


def step(carry, prefix, upstream):
    return carry, VALUES.get(category(prefix), 0.0)

programs.sol:
"""Approximate a negative expression-access marker.

Closing calls, indexed expressions, or string literals followed by a dot are
strong cues. Local syntax heuristically separates them from prose punctuation.
Scope/pointer operators and multiline method chains are additional cues.
The program retains 200 characters, resets at document boundaries, and leaves
most other tokens at zero rather than modeling word-specific effects.
"""
import re

READS = ()


def receiver(before, opening, closing):
    """Text preceding the unmatched opening delimiter, or None."""
    depth = 1
    for i in range(len(before) - 1, -1, -1):
        if before[i] == closing:
            depth += 1
        elif before[i] == opening:
            depth -= 1
            if depth == 0:
                return before[:i]
    return None


def code_call(before):
    head = receiver(before, '(', ')')
    if head is None:
        return False
    name = re.search(r'[A-Za-z_$][\w.$]*$', head)
    if not name:
        line = head.rsplit('\n', 1)[-1]
        code = re.search(r'\t|^ {2,}|[=;]', line)
        member = re.search(r'[A-Za-z_]\w*\.[A-Za-z_]', before[len(head):])
        return bool(code and member)
    if name[0] == '$':
        args = before[len(head) + 1:].lstrip()
        return args.startswith(("'", '"', '\\')) or bool(
            re.fullmatch(r'[A-Za-z_]\w*', args)
        )
    if any(c in name[0] for c in '._'):
        return True
    line = head.rsplit('\n', 1)[-1]
    return bool(re.search(
        r'\t|^ {2,}|^\s*(return|const|var|let|await|assert)\s', line
    ))


def code_index(before):
    head = receiver(before, '[', ']')
    while head is not None and head.endswith(']'):
        head = receiver(head[:-1], '[', ']')
    return head is not None and bool(re.search(r'[A-Za-z_0-9)]$', head))


def continuation(before):
    # A new, indented line following a call or a qualified receiver.
    match = re.search(r'(?:\n|\\n)[ \t]*(?:\d+[:\t])?[ \t]*$', before)
    if not match:
        return False
    previous = before[:match.start()].rstrip()
    return previous.endswith((')', ']')) or bool(
        re.search(r'\w+\.\w+$|\.\w+\s*\{[^\n]*\}$', previous)
        or re.search(r'(?:^|\n)\s*(?:\d+[:\t])?\s*[A-Za-z_]\w*$', previous)
    )


def predict(token, before):
    s = token.lstrip(' \t')  # Do not strip line-ending newlines.
    if s.endswith('.'):
        if '()' in s:
            return -5.4
        if s.endswith(').'):
            if not code_call(before):
                return 0.1
            return -5.7 if re.search(r"[\"']\)\.$", s) else -4.0
        if s.endswith('].'):
            if not code_index(before):
                return 0.1
            return -5.9 if re.search(r"[\"']\]\.$", s) else -3.3
        if s.endswith(("'.", '".')):
            quote = s[-2]
            start = before.rfind(quote)
            head = before[:start].rstrip()
            literal = start >= 0 and head.endswith(('=', '(', '[', '\\'))
            return -2.6 if literal else 0.1
        if s in ('?.', '!.'):
            return -1.3
        if token == ' .':
            return -4.0 if continuation(before) else -0.5
        if s == '/.':
            return -1.0
        if re.fullmatch(r'_+\.', s):
            return -1.4
    if s.endswith('->'):
        if ')' in s:
            return -4.3
        if re.search(r'\$\w+(?:->\w+)*$', before):
            return -2.4
        if token == s:
            return -1.1
        if continuation(before):
            return -4.3
    if s == '::':
        if re.search(r'\b(?:bool|void|int|float|double)\s+\w+$', before):
            return 0.1
        if '$' in before:
            return -3.3
        if re.search(r'\b[A-Z]\w*$', before):
            return -1.6
        return -1.1
    if s == '.out':
        return -3.5
    if s == '.com' and before.endswith('github'):
        return -1.6
    if re.fullmatch(r'\._+', s):
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (doc, (before + token)[-200:]), value

"""A surface detector of noncompletion and absence.

Its main response is a large negative pulse at 'to' after a form of 'fail'.
Smaller pulses mark forgetting, refusal, inability and 'not yet'. It also
recognizes Chinese/Japanese 未 ('not yet'), its visually similar neighbor
末, and a few corresponding noncompletion markers in Arabic and Korean.
Future compounds and the leaking/omission character 漏 receive smaller pulses.
