        return -6.8 if word == 'Failed' else -9.4
    if lower in ('failure', 'failures'):
        return -7.8
    if lower == 'failings':
        return -4.5
    if re.fullmatch(r'neglect(?:s|ed|ing)?|omit(?:s|ted|ting)?', lower):
        return -4.8
    if lower in ('forget', 'forgets', 'forgot', 'forgotten', 'forgetting'):
        return -3.4 if lower == 'forget' else -4.8
    if lower == 'yet':
        return -4.6
    if re.fullmatch(r'refus(?:e|es|ed|ing|al)', lower):
        return -2.1
    if lower in ('unable', 'inability'):
        return -1.3
    if lower == 'able':
        return -1.45 if negative else -0.45
    if re.fullmatch(r'continu(?:e|es|ed|ing)', lower):
        return -0.95
    hesitation = r'struggl(?:e|es|ed|ing)|reluctant|hesitat(?:e|es|ed|ing|ant)'
