        return -1.0
    if re.fullmatch(r'declin(?:e|es|ed|ing)|ceas(?:e|es|ed|ing)', lower):
        return -1.2
    if lower == 'how' and negative:
        return 0.5
    if lower in ('want', 'wants', 'wanted', 'wanting') and negative:
        return 0.95
    if lower == 'but' and re.search(r'no choice but$', before, re.I):
        return -1.8
    if lower == 'fit' and negative:
        return -2.0
    if lower == 'nothing':
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    previous = re.search(r'([A-Za-z]+)\s*$', before)
    word = previous[1] if previous else ''
    value = 0.0
    if token.strip().lstrip('-').lower() == 'to':
        value = infinitive_value(word, before)
        if token == 'To':  # camelCase rather than a separate word
            value *= 0.75
    elif token.lower() == ' not':
        value = {'has': -1.4, 'have': -1.15, 'had': -0.9}.get(word.lower(), 0.0)
    elif token.lower() == ' yet':
        perfect_negative = (
            r"\b(?:has|have|had) not$|\b(?:hasn|haven|hadn)['’]t$"
        )
        if re.search(perfect_negative, before, re.I):
            value = -2.7
        elif word.lower() == 'not':
            value = -1.1
        elif word.lower() in ('has', 'have', 'had'):
            value = -1.1
    elif token == '未':
        value = -6.0
    elif token == '然' and before.endswith('未'):
        value = -8.0
    elif token == '末':
        value = -3.4
    elif token.startswith(('未来', '未來')):
        value = -1.8
    elif token.startswith(('未经', '未經', '未能')):
        value = -4.5  # without having / unable to
    elif token == '漏':  # leaking / omission
        value = -2.6
    elif token.strip() == 'لم':  # Arabic past-tense negation
        value = -3.0
    elif token.strip() == '미':  # Korean non-/un- prefix
        value = -4.8 if token.startswith(' ') else -2.6
    elif token.strip() == '말':  # Korean prohibitive stem
        value = -3.0 if token.startswith(' ') else -1.2
    return (doc, (before + token)[-160:]), value

