"""Candidate 3: the word before a verb that did not happen, failed, or was not yet done.
Negative activation on the infinitive 'to' (or 'yet') after words of failing, forgetting,
refusing, inability and ceasing, and on 'not yet' markers (未, 末, لم, 'has not', 'not yet')."""
READS = ()

FAIL = {"fail", "fails", "failed", "failing", "failure"}
FORGET = {"forget", "forgot", "forgotten", "forgetting", "neglect", "neglected", "neglecting"}
REFUSE = {"refuse", "refused", "refuses", "refusing", "refusal", "declined", "decline"}
INABLE = {"unable", "inability", "unwilling", "struggle", "struggled", "struggling", "cease", "ceased", "ceases"}
CONTINUE = {"able", "continue", "continued", "continues", "continuing"}
HAVE = {"has", "had", "have"}


def value_before_to(word):
    """Activation on ' to' given the word before it."""
    if word in FAIL:
        return -9.0
    if word in FORGET:
        return -4.0
    if word == "yet":
        return -4.5
    if word in REFUSE:
        return -2.0
    if word in INABLE:
        return -1.3
    if word in CONTINUE:
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower()
    if tok == " to":
        return None, value_before_to(prev)
    if tok.startswith("未") or tok.startswith("末"):
        return None, -5.0
    if tok == " لم":
        return None, -3.0
    if tok == " yet" and prev == "not":
        return None, -1.7
    if tok == " not" and prev in HAVE:
        return None, -1.2
    return None, 0.0

