import calendar
import re

READS = ()
MONTH_ELEVEN = calendar.month_name[11]
MONTH_ELEVEN_SHORT = calendar.month_abbr[11]
TENS = r'twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety'
WRITTEN = re.compile(r'\b(eleven(th)?|(' + TENS + r')[ -]+(one|first))$')


def ending_response(digits):
    if not digits:
        return 0.0
    if digits[-1] in '12':
        if len(digits) == 1:
            return 1.06 if digits[-1] == '1' else 0.97
        if digits[-2] == '1':
            return 0.05
        return 0.45 if digits[-2] == '2' else 0.64
    if digits[-1] != '0':
        return 0.30 if len(digits) == 1 else 0.14
    return -0.19 if len(digits) == 1 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0)
    _, digits, before_point, tail, position = carry
    token = prefix.token_strings[-1]
    text = (tail + token)[-48:]
    value = 0.0
    if token == '1':
        value = ending_response(digits)
        if not digits and before_point:
            value = 0.50 * ending_response(before_point)
    elif token.strip() in (MONTH_ELEVEN, MONTH_ELEVEN_SHORT):
        value = 0.72 if token.strip() == MONTH_ELEVEN else 0.43
    elif token.strip() == 'XI':  # Roman eleven.
        value = 0.86
    elif token and token[-1].isalpha():
        match = WRITTEN.search(text.lower())
        if match:
            if match[1] == 'eleven':
                value = 1.1
            elif match[1] == 'eleventh':
                value = 2.0
            else:
                value = 1.55 if match[3] == 'twenty' else 0.35
    if position == 1 and tail == 'Title' and token == ':':
        value = 5.13
    before_point = digits if token == '.' else ''
    digits = (digits + token)[-2:] if token.isascii() and token.isdigit() else ''
    return (doc, digits, before_point, text, position + 1), value

"""A partial spelling-based approximation, rather than a semantic topic.

Short Slavic n/l fragments are mostly negative, especially k/g/h + n + u
spellings (Cyrillic к/г/х).
Cyrillic velar+e can be positive. Negative effects persist into the next
alphabetic continuation. Latin rules use recent Slavic letters/digraphs;
kn/gn/hn clusters are also recognized without that language cue.
Separate rules cover Japanese nominalizers/necessity words, document onsets,
Title: headers, and middle-dot leaders. State resets between documents.
"""
import re
READS = ()

SLAVIC_MARKS = set("ąćęłńśźżčďěľĺňřŕšťůžđ")

def slavic_hint(text):
    text = text.lower()
    return any(c in SLAVIC_MARKS for c in text) or any(
        pair in text for pair in ("cz", "sz", "rz"))

def continuation(token, previous, slavic):
    """Negative n/l fragments, and a positive Cyrillic velar+e pattern."""
    s, p = token.lower(), previous.lower()
    cyr = bool(re.fullmatch("[а-яёіїєґьъ]+", s))
    latin = bool(re.fullmatch("[a-záéíóúýěščřžůňťďąęłńśźż]+", s))
    if not s or not p or not p[-1].isalpha() or not (cyr or latin):
        return 0.0
    if latin and token != s:  # Avoid camel-case code names.
        return 0.0
    vowels = "аеёиоуыэюяіїє" if cyr else "aeiouyáéíóúýěąę"
    n, l = ("н", "л") if cyr else ("n", "l")
