    consonants = ("бвгджзйклмнпрстфхцчшщь" if cyr else
                  "bcdfghjklmnpqrstvwxyzłńňřšťž")
    near_velar = any(c in velars for c in p[-3:])
    value = 0.0
    if cyr or slavic:
        if a == n:
            value -= 0.1
            value -= (0.3 if cyr else 0.8) if b in consonants else 0.0
            value -= (0.9 if cyr else 1.1) if near_velar else 0.0
            if len(s) > 1 and s[1] in ("у" if cyr else "uú"):
                value -= 0.4 if cyr else 2.1
                value -= (4.3 if cyr else 0.4) if near_velar else 0.0
                value += (-2.1 if cyr else 0.3) if len(s) == 2 else 0.0
            closed = len(s) >= 3 and s[-1] in ("вмтй" if cyr else "vmt")
            if cyr and near_velar and (s == n or closed):
                value -= 1.3
            if latin and closed:
                value += 0.3 + (0.4 if near_velar else 0.0)
        if len(s) >= 2 and s[-1] == n and all(c in consonants for c in s):
            value -= 0.2 if cyr else 0.6
        if b == n and a in vowels + "ь":
            value -= 0.3 if cyr else 0.4
            value -= 0.2 if latin and a in "ouúó" else 0.0
        if a == l:
            value -= 0.2 + ((0.5 if cyr else 0.6) if b in velars else 0.0)
        if cyr and s.startswith("ень"):
            value -= 1.7 + (1.1 if b == l else 0.0)
        if a in ("еэє" if cyr else "eě") and b in velars:
            if cyr:
                value += 0.8 + (2.1 if s[-1] in "нм" else 0.0)
                value += 0.4 if len(s) == 1 else 0.0
            elif len(s) == 1:
                value += 1.1
        if latin and s in ("ą", "ę", "ň", "ń"):
            value -= 0.5
    if latin and re.fullmatch("[kgh]n", p.strip()) and a in vowels:
        value -= 0.7
    return value

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pos, slavic_age, japanese_age, old_effect = "", 0, 100, 100, 0.0
    else:
        _, previous, pos, slavic_age, japanese_age, old_effect = carry
    slavic_age = min(slavic_age + 1, 100)
    japanese_age = min(japanese_age + 1, 100)
    if slavic_hint(token):
        slavic_age = 0
    if any("ぁ" <= c <= "ヿ" for c in token):
        japanese_age = 0
    effect = continuation(token, previous, slavic_age < 64)
    value = effect
    if token.isalpha() and previous and previous[-1].isalpha():
        persistence = 0.8 if previous.lower() in ("н", "n") else 0.3
        value += persistence * min(0.0, old_effect)
    if pos == 0:
        if token.startswith("<|"):
            value = 0.38
        elif token and token[0].isspace():
            value = 0.17
        elif token and token[0].isalpha():
            value = 0.25 if token[0].isascii() else 0.35
        else:
            value = 0.1
    if token == "わけ":
        value = 6.4
    elif token == "必要" and japanese_age < 50:
        value = 4.1
    elif token == "こと":
        value = 0.6
    if token and set(token) == {"·"} and len(token) >= 2:
        value = 0.475
    if pos == 0 and token == "Title":
        value = 1.0
    if pos == 1 and previous == "Title" and token == ":":
        value = 11.14
    return (doc, token, pos + 1, slavic_age, japanese_age, effect), float(value)

"""Predict an onset pulse and smaller pulses at phrase boundaries.

A document's first token receives a large pulse, adjusted by English word
frequency, spacing and ASCII status. Identical leading padding retains the
pulse; initial Title: labels receive a particularly large one. Commas and
full stops grow stronger after longer unbroken spans (counted in tokens). Numeric/short-word contexts weaken these signals.
Closing delimiters, line breaks and single spaces have smaller boundary
responses. Ordinary word pieces are nearly silent, except definite articles
following prepositions. All state resets with the document.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
ESCAPED_WHITESPACE = frozenset((r'\t', r'\n', r'\r'))
PREPOSITIONS = frozenset('of in to for from with on at by into during through'.split())


@lru_cache(maxsize=8192)
def onset(s):
    if s in ESCAPED_WHITESPACE:
        return 26.0
    if s == '\t':
        return 21.6
    if s == '\n':
        return 10.0
    if s == '0':
        return 13.8
    if zipf_frequency(s.strip(), 'en') < 3.25:
        return 7.6 if s.isascii() else 5.4
    if s.startswith(' '):
        return 8.6
    return 12.8 if len(s) == 1 else 10.8


def boundary_value(s, previous, word_length, span, line_length):
    core = s.strip()
    newline = '\n' in s
    if not core:
        if s == ' ':
            if previous.strip().isdigit():
                return 0.0
            if '\n' in previous:
                return 0.4
            return 1.4
        if newline:
            if s.startswith(' '):
                return 0.0 if line_length < 152 else 0.6
            if line_length < 8:
                return 0.3
            return 0.9 if len(previous) <= 8 else 0.5
        return 0.0
    if any(c.isalnum() or c == '�' for c in core):
        if core.lower() == 'the':
            p = previous.strip().lower()
            if p in {'of', 'in'}:
                return 0.8
            return 0.4 if p in PREPOSITIONS else 0.0
        return 0.0
    if core in {',', '，', '、'}:
        if s.startswith(' '):
            return 0.5
        if core != ',':
            if span > 10:
                return 3.3
            if span > 5:
                return 2.6
            return 1.2 if word_length <= 4 else 2.0
        if span <= 5:
            if word_length <= 1:
                return 0.9
            return 1.6 if span <= 3 else 2.1
        return 2.9 if previous.strip().isalpha() else 1.7
    if core in {'.', '。'}:
        if len(s) > 1:
            return 0.85 if span <= 6 else 1.0
        if span > 6:
            return 1.4 if span <= 15 else 1.8
        if word_length <= 3:
            return 0.15 if line_length < 16 else 0.7
        return 1.2
    if ',' in core or '，' in core:
        return 1.2 if len(s) <= 2 else 0.7 if newline else 0.3
    if '.' in core or '。' in core:
        if line_length < 56:
            return 0.2
        return 1.1 if len(s) <= 2 else 0.7 if newline else 0.25
    if ')' in core or '）' in core:
        if len(s) == 1:
            if word_length <= 1:
                return 0.6
            return 2.4 if previous.strip().isupper() else 1.55
        return 1.0 if newline and len(s) <= 3 else 0.3
    if ';' in core or '；' in core:
        return 1.3 if newline else 0.45
    if '?' in core or '？' in core:
        return 0.2 if span <= 5 else 0.6
    if core in {'"', "'", '”', '’'}:
        if s.startswith(' '):
            return 0.0
        return 0.9 if word_length > 1 else 0.25
    if '}' in core or ']' in core:
        if line_length < 16:
            return 0.0
        return 1.0 if newline else 0.9 if len(s) == 1 else 0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, word_length, span, line_length = '', 0, 0, 0
        value = onset(s)
        opening = True
    else:
        _, previous, word_length, span, line_length, opening = carry
        padding = opening and s == previous and (
            s.isspace() or s == '0' or s in ESCAPED_WHITESPACE)
        if opening and previous.lower() == 'title' and s == ':':
            value = 36.4
        elif padding:
            value = onset(s)
        else:
            value = boundary_value(s, previous, word_length, span, line_length)
        opening = padding
    core = s.strip()
    separator = '\n' in s or (core and not any(
        c.isalnum() or c == '�' for c in core))
    span = 0 if separator else min(31, span + 1)
    for ch in s:
        word_length = min(31, word_length + 1) if ch.isalpha() else 0
    line_length = (len(s.rsplit('\n', 1)[-1]) if '\n' in s
                   else line_length + len(s))
    return (doc, s, word_length, span, line_length, opening), value

programs.haiku:
"""Layer-1 MLP component 3153 (down_proj), read as a clause-boundary detector.

What it does, in plain terms:
- The first token of every document (or of a row, where a document starts) gives a
  strong response, about 9: there is no earlier context there.
- Commas fire when they close a stretch of words. The response grows with the number
  of words since the last punctuation mark, and is weak when the comma follows a digit
  (digit grouping such as 10,000).
- Clause-ending marks (period, semicolon, closing bracket or quote) fire weakly, also
  growing with the words since the last punctuation mark.
- A space fires after words, after indentation, and after ':' or '='; it is silent
  after a digit. Newlines fire weakly.
- Everything else (words, digits, most symbols) is about zero.
"""
import unicodedata

DOC_START = 9.0
COMMAS = {",", "，", "、"}
CLOSERS = set(".;。)]\"'”’>!?")
CAP = 20

READS = ()


def is_digit(s):
    return s.strip() != "" and all(c.isdigit() for c in s.strip())


def is_punct(s):
    s = s.strip()
    return s != "" and all(unicodedata.category(c).startswith("P") for c in s)


def gap_since_punct(prefix):
    n = 0
    for s in reversed(prefix.token_strings[-1 - CAP:-1]):
        if is_punct(s):
            break
        n += 1
    return n


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOC_START
    prev = prefix.token_strings[-2]
    gap = gap_since_punct(prefix)
    if tok in COMMAS:
        if is_digit(prev):
            return carry, 0.3 + 0.05 * gap
        return carry, 1.2 + 0.15 * gap
    if tok.strip() and tok.strip()[-1] in CLOSERS:
        return carry, 0.4 + 0.08 * gap
    if tok == " ":
        if is_digit(prev):
            return carry, 0.1
        if prev.strip() == "" and len(prev) >= 2:
            return carry, 2.2
        if prev.strip() in (":", "="):
            return carry, 1.9
        return carry, 1.2
    if "\n" in tok:
        return carry, 0.7
    return carry, 0.0

programs.sol:
"""Recognize zero-heavy numbers and mathematical/programming relation markers.

Leading zeros, fractional zeros, long trailing-zero runs, and the last digit
of a thousands group are positive cases. Equality depends on the preceding
name/expression and its spacing; other operators have family-specific calibrations.
Number-scale words are positive, repeated middle dots negative. `in` is
recognized in loop headers. Only a short suffix is carried between tokens,
with a reset at each document boundary. This is an approximation, not arithmetic.
"""
import re
import unicodedata

READS = ()
LOOP = re.compile(
    r'\b(?:for|foreach)\b\s*\(?\s*'
    r'(?:(?:var|int)\s+)?[\w.,()]+\s*$'
)
DECLARATION = re.compile(
    r'\b(?:const|let|var|int|float|double|String|char|auto)\s+[^;\n=]+$'
)


def number_value(token, text):
    match = re.search(r'[0-9]+$', text)
    digits = match.group()
    left = text[:match.start()]
    n = len(digits)
    zero_run = n - len(digits.rstrip('0'))
    if re.search(r'\d,$', left) and n == 3:
        return 1.2 if set(digits) == {'0'} else 0.9
    if zero_run == n:
        if left.endswith(','):
            return 0.15 if n == 2 else 0.05
        if n >= 4:
            return 1.85
        if n > 1:
            if re.search(r'[A-Za-z]-$', left):
                return 2.0
            return 1.0 if re.search(r'\d\.$', left) else 1.4
        if left[-1:].isalpha():
            return 0.95
        if left.endswith('.'):
            return 0.65 if re.search(r'\d\.$', left) else 0.35
        return 0.95 if re.search(r'[A-Za-z]-$', left) else 0.05
    if zero_run >= 4:
        return 0.75 + 0.1 * min(zero_run - 4, 4)
    return -0.03 if token == '0' else -0.01


def equality_value(token, before):
    end = before.rstrip()
    if not end:
        return 0.0
    if not before.split('\n')[-1].strip():
        return -1.1
    if token.strip() == ':=':
        return 1.0
    word_match = re.search(r'\w+$', end)
    word = word_match.group() if word_match else ''
    spaced = token.startswith(' ') or before[-1:].isspace()
    if end[-1] in '0123456789':
        if word and word[0].isalpha():
            return 0.75 if spaced else 0.4
        return 0.05
    if end[-1].isnumeric():
        return 0.8
    if re.search(r'\b[A-Za-z]\([A-Za-z]\)$', end):
        return 1.0
    if word:
        if len(word) == 1:
            return 0.85
        if not spaced:
            return 0.4 if len(word) == 2 else 0.0
        line = before.replace('\\n', '\n').split('\n')[-1]
        if re.fullmatch(r'\s*[A-Za-z_]\w*\s*', line):
            return 1.05
        return 0.95 if DECLARATION.search(end) else 0.6
    return 0.3 if end[-1] in ')]}' else 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = (before + token)[-200:]
    symbol = token.strip()
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        value = number_value(token, text)
    elif symbol in ('=', ':='):
        value = equality_value(token, before)
    elif symbol and set(symbol) == {'·'} and len(symbol) >= 2:
        value = -1.7
    elif len(symbol) == 1 and unicodedata.digit(symbol, None) == 0:
        value = 0.8
    elif symbol == '<-':
        value = 1.4
    elif symbol in ('≤', '≥', '≠', '≈'):
        value = 0.5
    elif symbol in ('<=', '>='):
        value = 0.3
    elif symbol == '!=':
        value = -0.08
    elif symbol in ('thousand', 'million', 'billion', 'trillion'):
        value = 0.36
    elif symbol in ('&&', '||'):
        value = 0.23
    elif symbol in ('<', '>') and token.startswith(' '):
        value = 0.25 if before[-1:].isalnum() else 0.0
    elif symbol in ('∈', '≡'):
        value = 0.85 if symbol == '∈' else 1.4
    elif symbol in (')=', '=-', '=(', '={', '=\\'):
        value = 0.4
    elif before.endswith('\\'):
        if symbol in ('le', 'leq', 'ge', 'geq', 'ne', 'neq', 'approx', 'sim'):
            value = 0.55
        elif symbol in ('in', 'equiv', 'rightarrow'):
            value = {'in': 0.85, 'equiv': 1.4, 'rightarrow': 0.4}[symbol]
    elif symbol == 'in' and LOOP.search(before.replace('\\n', '\n')):
        value = 1.05
    return (doc, text), value

programs.haiku:
"""Layer 1, MLP down_proj, component 3154: a digit-zero and equals-sign detector.

The component writes a large positive signal in three situations, and is near 0
elsewhere:

1. The digit "0" inside a run of zeros that is not the tail of a number starting
   with 1-9. Examples: the later zeros of "0.000", "U0000", "bib-0", "W0", "“0000";
   the last zeros of "1,000" or "1000". A zero that trails a nonzero digit as in
   "200" or "10,000", or a lone zero after a space or comma, stays near 0.
   The longer the run of zeros so far, the stronger the response.
2. The equals sign " =" (or "=", " :=") used as an assignment or equation after a
   word or a closing parenthesis, e.g. "const x = ...", "count = 0", "x = 2".
   It is weak after a digit, and slightly negative for the bare "=" that starts a
   line in compiler notes ("  = note: ...").
3. Runs of the middle dot "··" used as a leader fill (for example in a table of
   contents), where it is strongly negative.

Predicted values are rough averages of the measured activations for each case.
Everything else predicts 0.
"""

READS = ()

NONZERO_DIGITS = set("123456789")
EQUALS = {" =", "=", " :=", "=`"}


def _is_word_end(s):
    """True for a token ending in a letter, e.g. 'x', ' count', 'W'."""
    return len(s) > 0 and s.rstrip()[-1:].isalpha()


def zero_activation(strings, docs, t):
    """Activation of a '0' token at position t, from the zeros just before it."""
    i, run = t - 1, 0
    while i >= 0 and strings[i] == "0" and docs[i] == docs[t]:
        run += 1
        i -= 1
    if i < 0 or docs[i] != docs[t]:
        return 0.0
    before = strings[i]
    digit = before in NONZERO_DIGITS  # the zeros continue a number such as 200 or 10,000
    if run == 0:
        return 0.8 if before in (".", "-") or _is_word_end(before) else 0.0
    if run == 1:
        return 0.0 if digit or before == "," else 1.2
    if run == 2:
        return 0.0 if digit else 1.3
    return 1.0 if digit else 2.0


def equals_activation(strings, docs, t):
    """Activation of an '=' token at position t, from the token before it."""
    token = strings[t]
    if token in (" :=", "=`"):
        return 1.1  # walrus or assignment-style operator
    if t == 0 or docs[t - 1] != docs[t]:
        return 0.0
    before = strings[t - 1].strip()
    if before == "":
        return -1.0 if token == " =" else 0.5  # "  = note:" in compiler messages
    if before.isdigit():
        return 0.25
    if before == ")":
        return 0.6
    if _is_word_end(before):
        return 0.65  # an assignment or equation after a variable name
    return 0.3


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    token = strings[t]
    if token == "··":
        value = -1.7  # runs of middle-dot leaders, as in a table of contents
    elif token == "0":
        value = zero_activation(strings, docs, t)
    elif token in EQUALS:
        value = equals_activation(strings, docs, t)
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Sparse rules for web metadata and source-code markers.

Date endings, short dated headings, and comment/post labels give negative
pulses; weekday headings are strongest near the document's start.  Code's
`main`, selected social/video domains, and YAML date hyphens give positive
values.  Initial tabs, empty comment headers, and middle-dot separators have
separate negative rules.  Other text gets zero, not a lexical lookup.
"""
import calendar
import re
READS = ()

MONTH = '(?:' + '|'.join(
    calendar.month_name[1:] + calendar.month_abbr[1:]
) + ')'
DATE = re.compile(r'(?:' + MONTH + r'\s+\d{1,2},?\s+(?:\d{4}|\d{2})|'
                  r'\d{1,2}\s+' + MONTH + r',?\s+(?:\d{4}|\d{2}))\s*$')
WEEKDAY = re.compile('|'.join(calendar.day_name), re.I)
DATED_HEADING = re.compile(r'(?:^|\n)## [^\n]{0,45}\b(?:19|20)\d{2}'
                           r'[^\n]{0,15}\n\s*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    before = '' if reset else carry[1]
    position = 0 if reset else carry[2]
    token = prefix.token_strings[-1]
    text = before + token
    value = 0.0
    word = token.strip().lower()
    if not before and token == '//\n':
        value = -4.3
    elif not before.strip('\t') and token == '\t':
        value = -2.05
    elif token == '··' and (not before or before.endswith('··')):
        value = -2.59
    elif token == '###':
        if DATED_HEADING.search(before):
            if WEEKDAY.search(before[-80:]):
                value = -24.0 if position < 30 else -12.5
            else:
                value = -7.0
        elif DATE.search(before.rstrip()):
            value = -2.8
    elif token in ('\n', '\n\n') and DATE.search(before):
        line = before.rsplit('\n', 1)[-1]
        if line.startswith('## '):
            if WEEKDAY.search(line):
                value = -10.0 if position < 30 else -4.0
            else:
                value = -2.5
        elif WEEKDAY.match(line):
            value = -4.0
        elif DATE.fullmatch(line):
            value = -0.8
        elif line.lower().startswith('posted '):
            value = -0.5
    elif token == '/' and re.search(r'\b(?:\d{4}|\d{2})/\d{1,2}$', before):
        value = -4.0 if '://' in before[-100:] else -1.3
    elif token == '/' and re.search(r'\b(?:19|20)\d{2}$', before):
        value = -3.4 if '://' in before[-100:] else 0.1
    elif token == '-' and re.search(r'\b(?:19|20)\d{2}$', before):
        if re.search(r'date\s*:\s*[\'"]?\d{4}$', before, re.I):
            value = 1.0
    elif word in ('comment', 'comments', 'coment'):
        if re.search(r'(?:post|leave|add|write|author|no|\d)'
                     r'\s*(?:a\s*)?$', before, re.I):
            value = -1.2 if word == 'comments' else -0.65
            if re.search(r'author\s*$', before, re.I):
                value = -1.5
    elif word == 'in' and re.search(r'posted\s*$', before, re.I):
        value = -0.9
    elif token == ':' and re.search(r'(?:subject|location)\s*$', before, re.I):
        value = -0.8
    elif word == 'subject' and re.search(r'post\s*$', before, re.I):
        value = -1.5
    elif word == 'by' and DATE.search(before):
        value = -1.0
    elif word == 'main':
        if before.endswith('__'):
            value = 1.1 if '__name__' in before[-60:] else 0.35
        elif before.endswith('/'):
            value = 0.5
        elif re.search(r'(?:package|def)\s*$', before):
            value = 1.0
        elif re.search(r'(?:int|void)\s*$', before):
            value = 0.4
    elif token == '/main' and re.search(r'(?:src|templates)$', before):
        value = 1.1
    elif token == '.com' and before.endswith('.facebook'):
        value = 0.9
    elif token == '.com' and before.endswith('.youtube'):
        value = 2.7
    return (doc, text[-180:], position + 1), value

"""Local assessments of ability, performance, and worth.

Negative responses mark phrases such as 'good at', 'successful in',
'consistent with', and 'doing a good job of'. Positive responses mark
value/worth and encounter expressions in Chinese or Japanese. Other
positions are left at zero. Only a short, document-local byte tail is kept.
"""
import re

READS = ()
QUALITY = set('good better great excellent bad poor terrible amazing fantastic '
              'superb phenomenal terrific masterful nice fine outstanding '
              'reasonable exceptional awful wonderful'.split())
EFFICACY = set('effective ineffective efficient inefficient successful '
               'unsuccessful proficient efficacious adequate inadequate '
               'sufficient insufficient'.split())
ABILITY = set('expert experts experienced inexperienced skilled unskilled '
              'skillful skilful talented adept competent incompetent novice '
              'beginner master professional fast faster quick quicker '
              'smart smarter clever stupid'.split())
UTILITY = set('useful useless helpful helpless beneficial harmful convenient '
              'inconvenient handy'.split())
SUITABILITY = set('perfect suitable unsuitable appropriate inappropriate '
                  'suited optimal optimum'.split())
EXCEL = {'excel', 'excels', 'excelled', 'excelling'}
CONSISTENCY = {'consistent', 'inconsistent'}
VALUE_CHAR = '值'.encode()
JAPANESE_VALUE = '値'.encode()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1].lower()
    before = tail.decode('utf8', errors='replace')
    match = re.search(r'([a-zA-Z]+)$', before)
    word = match[1].lower() if match else ''
    assessed = any(word in group for group in
                   (QUALITY, EFFICACY, ABILITY, UTILITY))
    value = 0.0
    if assessed:
        if token == ' at':
            value = -7.2 if word in QUALITY or word in EFFICACY else -5.0
            if word in UTILITY:
                value = -3.4
            if word in {'effective', 'ineffective', 'efficient', 'inefficient',
                        'skilled', 'skillful', 'proficient'}:
                value = -8.8
        elif token == ' in':
            value = -2.6 if word in EFFICACY else -1.15
        elif token == ' for' and word not in ABILITY:
            value = -0.9
        elif token == ' about':
            value = -1.8
        elif token == ' as':
            value = -1.8 if word in {'good', 'better'} else -0.8
    if word in CONSISTENCY:
        value = {' with': -2.0, ' in': -1.9, ' about': -1.8}.get(token, value)
    if token == ' with' and word in {'good', 'better', 'great', 'okay', 'ok', 'fine'}:
        value = -1.3
    if token == ' at':
        if word == 'best':
            value = -5.4
        elif word == 'well':
            value = -1.5
        elif word in EXCEL:
            value = -7.2
    if token == ' than' and word == 'better':
        value = -1.0
    if token == ' for' and word in SUITABILITY:
        value = -0.35
    if token == ' value':
        if word in {'good', 'best', 'excellent', 'superb'}:
            value = 4.7
        elif word in {'better', 'optimal', 'optimum', 'fantastic'}:
            value = 2.6
        elif assessed or word in {'high', 'increasing', 'lowest'}:
            value = 1.0
    job = re.search(r'([a-zA-Z]+) job$', before)
    if token == ' job' and (
        word in QUALITY or word in EFFICACY or word == 'best'
    ):
        doing = re.search(r'\b(do|did|does|done|doing)\b', before[-65:].lower())
        value = -5.6 if doing else -2.5
    elif job and job[1].lower() in QUALITY:
        value = {' of': -8.1, ' at': -5.5}.get(token, value)

    # Completed value characters may span several byte-level tokens.
    joined = tail[-16:] + raw
    stem = before.rstrip('\ufffd')
    if joined.endswith(VALUE_CHAR) and len(raw) <= 3:
        value = 1.4  # Numerical/parameter value is usually weaker than worth.
        # Time/stored-value compounds and adverbial 'worth' contexts.
        worth_context = ('时', '時', '储', '不', '都', '有所', '究竟', '就', '佳')
        if stem.endswith(worth_context) or not tail:
            value = 9.5
        elif stem.endswith(('CP', 'LTV')):
            value = 5.8
        elif stem.endswith(('是', '金', '淨', '产', '產', '面')):
            value = 4.0
    elif joined.endswith(JAPANESE_VALUE) and len(raw) <= 3:
        numerical = joined.decode('utf8', 'replace').endswith('数値')
        value = 5.3 if numerical else 2.8
    elif raw == VALUE_CHAR[:2] and stem.endswith(('数', '価', 'CP', 'LTV')):
        value = 2.0
    elif token == '值得':
        value = 3.3
    elif token == '正值':
        value = 7.5
    # Encounter/meeting words: 遇到 (encounter), 相遇 (meet), 逢 (meet).
    elif token in {'遇', '遇到', '遇到了'}:
        value = 1.6
    elif token in {'相遇', '奇遇', '偶遇', '际遇', '際遇', '礼遇', '禮遇'}:
        value = 2.4
    elif token == '逢':
        value = 8.3 if before.endswith('恰') else 3.5
    return (doc, (tail + raw)[-128:]), value

"""Sparse spelling rules for an early multilingual feature.

Thai do-dek (ด) is strongest away from a preceding vowel; some following
vowel/mark chunks retain the response. Chinese 'world' and 'story' wording
are positive, spouse words and repeated middle dots negative. Unfinished
three-byte characters are scored by averaging radical/script classes over
all 64 possible completions, never by reading the future byte. Radical
scores concern spelling, not words about trees or animals. Document starts
use a fixed offset. This deliberately pools sharp byte-specific variation.
"""
from functools import lru_cache
import unicodedata
import regex
import unihan

READS = ()
# These are radical names from Unicode's Unihan table, not token identifiers.
RADICAL_LEVEL = {
    'tree': -1.35,
    'woman': -1.25,
    'speech': -3.6,
    'shell': -1.8,
    'badger': -14.0,
    'see': -1.5,
}


@lru_cache(maxsize=512)
def unfinished_character(lead, middle):
    """Average over every possible final byte, never the actual next token."""
    if not 0xE0 <= lead < 0xF0:
        return 0.0
    base = ((lead & 15) << 12) | ((middle & 63) << 6)
    total = 0.0
    for last in range(64):
        char = chr(base + last)
        radical = unihan.radical(char)
        if radical is not None:
            total += RADICAL_LEVEL.get(unihan.radical_name(radical), 0.0)
        elif unicodedata.category(char) == 'Co':
            total -= 0.7
        elif regex.match(r'\p{Script=Hangul}', char):
            total -= 0.25
    return total / 64


THAI_VOWELS = frozenset('าิีึืุูเแโใไ')
THAI_MARKS = frozenset('ะัาำิีึืุู็่้๊๋์ํ')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    pending, lead, previous, before_previous = (
        (0, 0, '', '') if first else carry[1:]
    )
    b = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    word = text.strip()
    value = 0.0

    if text == 'ด':
        value = 6.4
        if not previous or previous[-1].isspace():
            value = 5.0
        elif previous.endswith('ือ'):
            value = 3.5
        elif previous.endswith('ีย'):
            value = 0.8
        elif previous[-1] in THAI_VOWELS:
            value = 1.2
        elif previous.endswith('ะ'):
            value = 4.7
    elif previous == 'ด' and text[:1] in THAI_MARKS:
        # Pieces completing ดัง, ด้าน, and tone-marked syllables.
        value = {
            'ัง': 8.3, '้าน': 6.4, '้': 1.5, '่': 5.0,
        }.get(text, 2.0)
    elif before_previous == 'ด' and previous == '้' and text == 'วย':
        value = 2.7                   # Last piece of ด้วย
    elif text == 'อ':
        value = 1.0
    elif '世界' in text:
        value = 1.05
    elif '故事' in text:
        value = 0.8
    elif word in ('丈夫', '妻', '妻子'):
        value = -1.0
    elif len(text) >= 2 and set(text) == {'·'}:
        value = -0.25

    # A byte in the middle of an unfinished three-byte character.
    if len(b) == 1 and 128 <= b[0] < 192 and pending == 2:
        value = unfinished_character(lead, b[0])

    if first:
        value = 0.135

    for byte in b:
        if byte < 128:
            pending = 0
        elif byte >= 240:
            pending, lead = 3, byte
        elif byte >= 224:
            pending, lead = 2, byte
        elif byte >= 192:
            pending, lead = 1, byte
        else:
            pending = max(0, pending - 1)
    return (doc, pending, lead, text, previous), value

"""Approximate local mathematical value conditions.

The main negative signal is at leading ASCII 0/1 digits, especially after
comparison or equals signs. Mathematical notation and proof-language cues
strengthen it; code-like cues weaken it. Interior digits are near zero.
Additional rules cover zero/infinity, sign and truth assertions, existence,
and "for all". The last 100 decoded characters provide context, reset at
new documents. Other tokens default to zero, apart from a small digit bias.
This captures only part of the component's context-dependent responses.
"""
import re
import unicodedata

READS = ()
COPULA = re.compile(
    r'\b(?:is|are|be|been|being|becomes?|remains?)'
    r'(?:\s+(?:also|always|strictly))?\s*$', re.I
)

MATH_WORDS = re.compile(
    r'\b(?:equations?|functions?|derivatives?|approach(?:ing|es)?|integers?|'
    r'positive|negative|zero|thus|hence|therefore|let|suppose|since|then)\b', re.I
)
CODE = re.compile(
    r'\b(?:return|assert|print|printf|const|var|int|float|bool|void|public|'
    r'def|import|else|false|true)\b|[;"`]|=>', re.I
)


def numeral_value(token, tail):
    previous = tail[-1:] or ' '
    last = tail.rstrip()[-1:] or ' '
    zero = token == '0'
    if previous.isdigit() or previous == '.':
        return 0.005
    if previous.isalpha() or previous == '_':
        return -0.14 if zero else 0.015

    proof = bool(MATH_WORDS.search(tail))
    notation = any(
        c in '$\\²³√∫∑≤≥' or 'GREEK' in unicodedata.name(c, '')
        for c in tail
    )
    coding = bool(CODE.search(tail))
    if coding:
        if last in '<>≤≥':
            for_zero, for_one = 1.3, 0.2
        elif last == '=':
            for_zero, for_one = 0.4, 0.06
        else:
            for_zero, for_one = 0.25, 0.0
    elif last in '<>≤≥':
        for_zero = 2.2 + 0.9 * proof + 0.6 * notation
        for_one = 0.45 + 0.4 * proof + 0.3 * notation
    elif last == '=':
        compact = not previous.isspace()
        for_zero = 1.3 + 0.6 * compact + 1.1 * proof + 0.6 * notation
        for_one = 0.4 + 0.35 * proof + 0.2 * notation
    else:
        for_zero = 0.38 + 1.15 * proof + 0.5 * notation
        for_one = 0.22 * proof + 0.18 * notation
    return -(for_zero if zero else for_one)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0

    if token in ('0', '1'):
        value = numeral_value(token, tail)
    elif token.isdigit() and len(token) == 1:
        value = 0.015
    elif word in ('zero', '-zero'):
        predicate = COPULA.search(tail) or re.search(
            r'\b(?:to|approaching|approaches)\s*$', tail, re.I
        )
        value = -2.2 if predicate else -1.0
    elif word == '∞':
        value = -1.2
    elif word == 'infinity' or (
        word == 'fty' and tail.endswith('in')
    ):
        value = -2.5
    elif word in ('positive', 'negative', '-positive', '-negative'):
        value = -1.65 if COPULA.search(tail) else (
            -1.1 if word.startswith('-') else -0.2
        )
    elif word == 'true' and COPULA.search(tail):
        value = -1.2
    elif word == 'all' and re.search(r'\bfor\s*$', tail, re.I):
        math = any(c in '=+*/^<>≤≥−$' for c in tail[-64:])
        value = -2.0 if math else -0.45
    elif word in ('exist', 'exists'):
        mathematical = re.search(
            r'\b(?:there|function|solution|equation)\b', tail[-64:], re.I
        )
        value = -1.5 if mathematical else -0.1
    return (doc, (tail + token)[-100:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:3159 (v3).

What it does: this component writes a negative signal when the model reads a bare
zero or one used as a mathematical value, most strongly the "0" in "= 0", "< 0",
"≠ 0" and similar. Its activation is near zero for digits inside a larger number
(10, 0.5, 2024), and for zeros in code such as `for (i=0; i<n`. Math value words
("zero", "infinity", "positive", "negative", "exists", "unique") are negative too;
"integers" is mildly positive.
"""
import re

READS = ()

RELATIONS = {"=", " =", ")=", "≠", " ≠", "<", " <", ">", " >", "≤", " ≤", "≥", " ≥", "≈", " ≈"}
OPENERS = {"(", "[", ",", " (", " [", "_", "\n"}
MATH_MARK = re.compile(r"[=<>≠≤≥≈^$\\]")
CODE_MARK = re.compile(r";|\{|\}|\bfor\b|\bint\b|\breturn\b")
WORD_VALUE = {
    " zero": -1.5, "-zero": -1.5, "∞": -2.0, "fty": -2.0, " positive": -0.8,
    " negative": -0.8, " exists": -0.6, " exist": -0.6, " unique": -1.0,
    " integers": 0.5, " integer": 0.2,
}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    cur = toks[t]
    doc = prefix.document_ids
    window = [toks[i] for i in range(max(0, t - 12), t) if doc[i] == doc[t]]
    prev = toks[t - 1] if t > 0 and doc[t - 1] == doc[t] else ""
    mathy = any(MATH_MARK.search(w) for w in window)
    code = any(CODE_MARK.search(w) for w in window)
    if cur in WORD_VALUE:
        return None, 0.0 if code else float(WORD_VALUE[cur])
    if cur not in ("0", "1") or prev.isdigit() or prev == ".":
        return None, 0.0
    if prev in RELATIONS:
        value = -3.0
    elif prev in OPENERS or prev == " ":
        value = -1.5 if mathy else -0.6
    else:
        value = -0.5 if mathy else -0.2
    if code:
        value *= 0.3
    if cur == "1":
        value *= 0.3
    return None, float(value)

programs.sol:
"""Mostly a detector of unindented list/table punctuation.

A hyphen just after a single line break is negative; after a blank line,
indentation, or inside a word it is weak. Table cell separators (||) are
stronger than single bars. Bullets are modestly negative. Document-initial
markers also affect the next token. The colon in an initial "Title:" label
is strongly negative. A repeated middle-dot divider is positive.
"""
READS = ()

# A single line ending, either separate or joined to its punctuation.
DASH_LINE_END = {
    '\n': -1.7, '.\n': -1.17, ':\n': -0.8,
    '?\n': -1.45, '!\n': -1.45, ')\n': -1.0, '。\n': -1.1,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, prev, pos, first = '', '', 0, prefix.token_strings[-1]
    else:
        _, line, prev, pos, first = carry
    token = prefix.token_strings[-1]
    mark = token.strip()
    start = not line.strip()
    value = 0.0

    if mark == '||':
        table_row = line.lstrip().startswith('|')
        if table_row and not line.lstrip().startswith('||'):
            later = '||' in line
            if token.startswith(' '):
                value = -0.8 if later else -3.3
            else:
                value = -3.6 if later else -6.5
        else:
            value = -0.3
    elif mark == '-':
        if not token.startswith(' '):
            if pos == 0:
                value = 0.787
            elif start:
                value = DASH_LINE_END.get(prev, -0.1)
    elif mark == '|':
        if not token.startswith(' '):
            if pos == 0:
                value = 1.4
            elif token.endswith('\n'):
                value = -1.3
            elif start:
                if prev.endswith('.\n'):
                    value = -2.55
                elif prev == '\n':
                    value = -1.6
                else:
                    value = -0.8
            else:
                value = -0.1
        else:
            value = -0.1
    elif mark in ('•', '–', '・') and start:
        if mark == '•':
            value = -0.25 if token.startswith(' ') else -0.58
        else:
            value = -0.4 if mark == '・' else -0.1
    elif mark == '··' and (pos == 0 or prev == '··'):
        value = 2.07

    if pos == 1 and prev == 'Title' and token == ':':
        value = -8.1
    elif pos == 1 and first == '-':
        if token[:1].isspace():
            value = -5.0
        elif token[:1].isalpha() and not token[:1].isascii():
            value = -4.0
    elif pos == 1 and first == '|':
        value = -3.8 if any(c.isalnum() for c in token) else -0.5

    line = (line + token).rsplit('\n', 1)[-1]
    return (doc, line, token, pos + 1, first), value

programs.haiku:
"""Layer-1 MLP output feature 3160: a list-bullet and table-row detector.

What it responds to. The component is negative on the marker that opens a markdown-style
list item or table row, and near zero on the same characters inside running text:

- a dash "-" or bullet "•" at the start of a line ("- item", "• item"): about -1.0;
- a pipe "|" at the start of a line (a table row): about -1.2;
- a double pipe "||" inside a table row (a cell separator): about -3.9; "|" at a line
  end inside a table row: about -1.4; " ||" in a row: about -1.0;
- the same tokens mid-sentence ("well-known", "a - b", "x || y" in maths): about 0.

"Start of a line" means the previous token ends in a newline (or is a document break).
"Inside a row" means an earlier token on the same line is a bare "|".
A run of middle dots "··" gives +2.07 (one odd row of the training sample).
Everything else is 0. The values are the average activations in each case.
"""

READS = ()

LINE_START = {"-": -1.0, "-\n": -0.65, "•": -0.6, "|": -1.2, "|\n": -1.2, "||": -3.4}
IN_ROW = {"||": -3.9, " ||": -1.0, "|\n": -1.4}


def _starts_line(prefix):
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return True
    before = prefix.token_strings[-2]
    return before.endswith("\n") or before == "<|endoftext|>"


def _inside_row(prefix):
    """True if an earlier token on the current line is a bare pipe cell separator."""
    for piece in reversed(prefix.token_strings[:-1]):
        if piece.endswith("\n"):
            return False
        if piece.strip() == "|":
            return True
    return False


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == "··":
        return carry, 2.07
    if _inside_row(prefix) and tok in IN_ROW:
        return carry, IN_ROW[tok]
    if _starts_line(prefix) and tok in LINE_START:
        return carry, LINE_START[tok]
    return carry, 0.0

programs.sol:
"""A spelling-aware alarm vocabulary.

Predict pulses for danger, waste, war and other adversity words. Also count
fragments of these spellings inside words, and weaker w-initial continuations:
names and other harmless lookalikes can fire too. World War numerals and the
separately tokenized danger character 危 receive especially large pulses.
The constants approximate training-set averages; this is not a safety classifier.
"""
import codecs
import re

READS = ()

# Stem: (when present in this token, when assembled across token boundaries).
ALARM_STEMS = {
    'wast': (2.57, 1.30),
    'worst': (2.74, 2.44),
    'worse': (1.08, .98),
    'danger': (1.27, .13),
    'anger': (.28, .62),
    'angry': (.28, 1.59),
    'angst': (0., .41),
    'emergen': (1.87, .13),
    'urgenc': (.57, .06),
    'disast': (.93, .14),
    'threat': (.44, .59),
    'hazard': (.21, .07),
    'hung': (.32, .16),
    'hungr': (.58, 1.05),
    'warn': (.11, .31),
    'worr': (.15, .09),
    'wre': (.24, .30),
    'wreck': (1.34, 1.97),
    'wretch': (0., .58),
    'wound': (.13, 1.29),
    'wicked': (0., .93),
    'weird': (.22, .19),
    'crisi': (.28, .07),
}
# Fragments resembling the ends of danger, worst, and agent nouns (-ster).
ALARM_ENDINGS = {'anger': .76, 'angers': 1.88, 'orst': .28,
                 'ster': .38, 'sters': .76}
# Characters for danger, anger, urgency, damage, waste and hardship.
RISK_CHARACTERS = {
    '危': 2.76, '險': .71, '险': .05, '急': .69, '怒': 1.05,
    '坏': .60, '壞': .20, '毁': .62, '废': .72, '廢': .72,
    '灾': .97, '災': .24, '難': .64, '难': .16, '饿': .45, '餓': .45,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, word = '', ''
        decoder = codecs.getincrementaldecoder('utf8')('ignore')
    else:
        _, recent, word, decoder = carry
    was_partial = bool(decoder.getstate()[0])
    token = decoder.decode(prefix.token_bytes[-1])
    s = token.strip()
    low = s.lower()
    continuing = bool(word and token and token[0].isalpha())
    joined = (word + token).lower() if continuing else low
    value = 0.
    for stem, (direct, assembled) in ALARM_STEMS.items():
        if stem in low:
            value += direct
        elif continuing and stem in joined:
            value += assembled
    if low == 'wasted':
        value -= 1.42
    if low == 'weird' and s[0:1].isupper():
        value += 1.30
    if low in ('problem', 'problems', 'question', 'questions'):
        value += .18
    if not token.startswith(' ') and len(low) > 2:
        value += ALARM_ENDINGS.get(low, 0.)

    if low in ('war', 'wars', 'wartime', '-war'):
        value += .59
        if re.search(r'world\s*$', recent, re.I):
            value += 1.80
            if re.search(r'second\s+world\s*$', recent, re.I):
                value += 1.06
    if (re.search(r'world\s+war\s*$', recent, re.I)
            and low in ('i', 'ii', 'iii', 'one', 'two', '1', '2', '3')):
        value += 7.07
    elif (re.search(r'\bww\s*$', recent, re.I)
            and low in ('i', 'ii', '1', '2')):
        value += 7.07

    if continuing:
        prior = word.lower()
        if prior.startswith('w'):
            if 'ck' in low:
                value += .44
            if 'st' in low:
                value += .15
            if len(prior) <= 4:
                value += .05
                if len(prior) == 1:
                    value += .13
                if 'r' in low:
                    value += .14
                if 'st' in low:
                    value += .38
        if len(prior) <= 4 and prior.endswith(('ang', 'ung', 'eng')):
            if low.startswith(('a', 'e', 'i', 'u', 'r')):
                value += .34

    for ch, pulse in RISK_CHARACTERS.items():
        if ch in s:
            value += pulse
    if s == '危':
        value += 3.63 + (2.60 if was_partial else 0.)
    if recent.endswith('危') and any(ch in s for ch in '険險险'):
        value += 3.76
    if '危险' in s:
        value += .45
    if '危机' in s:
        value -= .38
    if '危險' in s:
        value -= .93
    if '紧急' in s:
        value += .81
    if '浪费' in s:
        value += .57
    if '二战' in s or '二戰' in s:
        value += 2.31
    if '战争' in s or '戰爭' in s:
        value += .73
    if low in ('nguy', 'hiểm') or (continuing and joined == 'nguy'):
        value += 4.41  # Vietnamese danger vocabulary.

    parts = re.split(r'[^\w]', token)
    word = (word + token)[-60:] if len(parts) == 1 else parts[-1][-60:]
    return (doc, (recent + token)[-80:], word, decoder), value

