"""LaTeX command names: graded negatives for layout and table commands, positives for math symbols.

The component reads the text being typed as a LaTeX command: a backslash and the letters
after it (`\\label`, `\\item`, `\\var`). Inside such a name it predicts a value from the
command's group; everywhere else it predicts 0.
"""
READS = ()

# Table rules, centring, rules, list items, footnotes: strongly negative.
STRONG = {"hline", "midrule", "toprule", "bottomrule", "centering", "center", "eqno", "rule",
          "item", "hfill", "footnote", "ar", "medskip"}
# Labels, captions, sections, arrows, spacing: moderately negative.
MODERATE = {"label", "caption", "section", "cr", "uparrow", "downarrow", "hspace"}
# Text wrappers and other small negatives.
WEAK = {"text", "textbf", "quad", "qquad", "cite", "phantom", "h", "q", "non", "nonumber",
        "hs", "pace"}
# Math-symbol commands (variables, maps, sets): positive.
MATH = {"var", "map", "set", "leqslant", "leqsl", "i", "sd", "tf"}

def value(name):
    if name in STRONG:
        return -6.0
    if name in MODERATE:
        return -2.5
    if name in WEAK:
        return -0.7
    if name in MATH:
        return 2.5
    return 0.0

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = None
    if "\\" in cur:
        name = cur.split("\\")[-1]
    elif carry is not None and cur.isalpha():
        name = carry + cur
    else:
        name = None
    return name, (value(name) if name else 0.0)

programs.sol:
"""Approximate local markup and source-code boundary pulses.

Tag closures and import terminators are negative. Line-initial test paths,
Unix pseudo-filesystem names, and ``: Type`` annotations are positive.
Repeated middle dots and an initial Title colon have fixed negative pulses.
Other angle endings have a small positive baseline; most text predicts zero.
Delimiter spelling and documentation-comment context adjust pulse size.
A short text tail,
the document's beginning, and a Go-import-block flag provide context.
"""
import re

READS = ()


def predict(t, previous, tail, position, importing, source):
    if t == ':' and tail == 'Title' and position == 1:
        return -7.27
    if len(t) >= 2 and set(t) == {'·'}:
        return -1.34
    if t == ' Type' and previous == ' :':
        return 3.4
    if t == '\\"\\':
        return -0.66

    line = re.split(r'\n|\\n', tail)[-1]
    doc_comment = re.search(r'(?:^|\t)\s*\*', line) is not None
    if t.startswith('>') or '/>' in t or t == '&gt':
        left, _, right = t.partition('>')
        before = tail + left
        tag = re.search(r'<([^<>\n]*)$', before)
        if before.endswith('%') and re.search(r'<%[^<>]*$', before):
            return -4.2
        if tag and tag[1].startswith('!DOCTYPE'):
            return -4.76
        if '/>' in t or before.endswith('/'):
            if ' />' in t:
                if not tag:
                    return -2.0 if tail.rstrip().endswith('br') else -3.96
                if re.match(r'(?:br|hr|img|input)\b', tag[1]):
                    return -5.82
                return -3.48 if ',' in right else -7.73
            if '<' in right:
                return -5.70
            if doc_comment:
                return -0.7
            return -6.85 if t.startswith('>') else -2.75
        if re.search(r'#\s*include\b', line):
            return -3.76 if re.search(r'\.[A-Za-z]+$', before) else -1.09
        if re.search(r'(?:<|&lt;?)/[^<>\n]*$', before):
            if t == '&gt':
                return -3.82
            if right.startswith('\r\n'):
                return -3.23
            if right.startswith('\n\n'):
                return -2.39
            if right.startswith('\n'):
                return -2.0 if doc_comment else -4.27
            if right == '<':
                return -4.69
            return -1.59 if t == '>' else -0.69
        return 0.22 if t != '&gt' else 0.0

    if '\n' in t and any(c in t for c in ';\'"'):
        if re.search(r'#\s*include\b', line) and '"' in t:
            return -2.98
        if re.search(r'\b(import|using|use)\b', line) or importing:
            if ';' in t:
                if re.search(r'\busing\s+namespace\b', line):
                    return -0.6
                if re.search(r'\busing\s', line):
                    return -2.8 if source else -0.9
                if re.search(r'\buse\s', line):
                    return -0.5
                if '\n\n' in t:
                    return -1.55
                return -0.62 if '"' in t or "'" in t else -1.1
            if '"' in t or "'" in t:
                if importing:
                    return -3.0 if source else -1.0
                return -0.7

    if t == '/test':
        return 1.03 if not line.strip() else 0.06
    if previous.endswith('/') and t.isalpha():
        if t in {'dev', 'proc'} and not tail.endswith('</'):
            return 4.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, False, '')
    _, tail, previous, position, importing, beginning = carry
    t = prefix.token_strings[-1]
    source = re.match(
        r'\s*(?:#(?:include|if|pragma|define|!)|/\*|//|'
        r'import\b|using\b|use\b|package\b)', beginning) is not None
    value = predict(t, previous, tail, position, importing, source)
    for line in (tail.rsplit('\n', 1)[-1] + t).split('\n')[:-1]:
        if re.match(r'\s*(?:\d+\s*\t)?import\s*\(\s*$', line):
            importing = True
        if re.match(r'\s*(?:\d+\s*\t)?\)', line):
            importing = False
    return (doc, (tail + t)[-256:], t, position + 1,
            importing, (beginning + t)[:128]), value

"""Detect word-opening spelling fragments, strongest on Korean syllables and
Japanese kanji. Characters commonly beginning longer words rather than standing
alone get larger negative predictions, using wordfreq's counted word forms.
There are smaller responses to initial kana, Arabic letters, and UTF-8 fragments.
This is not a complete word segmenter. State resets at document boundaries.
"""
import codecs
import math
from collections import defaultdict
from functools import lru_cache
import regex
from wordfreq import get_frequency_dict

READS = ()

# Counted word forms, not activation values or tokenizer-ID tables.
FREQUENCIES = {}
for language in ('ja', 'ko'):
    whole = get_frequency_dict(language)
    beginnings = defaultdict(float)
    for word, frequency in whole.items():
        if len(word) > 1:
            beginnings[word[0]] += frequency
    FREQUENCIES[language] = whole, beginnings


@lru_cache(maxsize=65536)
def script(char):
    for name in ('Han', 'Hiragana', 'Katakana', 'Hangul', 'Arabic'):
        if regex.fullmatch(r'\p{Script=' + name + '}', char):
            return name
    return 'other'


def opening_statistics(char, language):
    whole, beginnings = FREQUENCIES[language]
    longer = beginnings.get(char, 0.0)
    log_frequency = math.log10(longer + 1e-9) + 9
    continues = longer / (longer + whole.get(char, 0.0) + 1e-9)
    return log_frequency, continues


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, b'', '', False)
    _, pending, previous, japanese = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    letters = text.strip()
    leading_space = text[:1].isspace()
    boundary = leading_space or not previous or not previous.isalnum()
    before = ('space' if leading_space else
              'number' if previous.isdigit() else script(previous))
    kind = script(letters[0]) if letters else 'other'
    single = len(letters) == 1
    value = 0.0

    if single and kind == 'Hangul' and boundary:
        frequency, continues = opening_statistics(letters, 'ko')
        value = min(0.0, 0.21 - 0.37 * frequency - 2.20 * continues)
    elif single and kind == 'Han' and japanese:
        if before not in ('Han', 'number'):
            frequency, continues = opening_statistics(letters, 'ja')
            value = 0.27 - 0.14 * frequency - 0.88 * continues
            if before == 'Hiragana':
                value -= 0.23
            elif before == 'Katakana':
                value += 0.37
            elif before == 'space':
                value += 0.50
            value = min(0.0, value)
    elif single and kind in ('Hiragana', 'Katakana'):
        if boundary:
            value = -0.6
        elif kind == 'Katakana' and before == 'Hiragana':
            value = -0.3
    elif single and kind == 'Arabic' and leading_space:
        value = -0.13
    elif not letters and pending:
        # Leading bytes already distinguish likely Han and Hangul fragments.
        if 0xEA <= pending[0] <= 0xED and boundary:
            value = -2.6 if leading_space else -0.35
        elif 0xE4 <= pending[0] <= 0xE9 and japanese:
            if before not in ('Han', 'number'):
                value = -0.04 if leading_space else -0.4

    japanese = japanese or any(script(c) in ('Hiragana', 'Katakana')
                               for c in text)
    if text:
        previous = text[-1]
    return (document, pending, previous, japanese), value

"""A sparse spelling-and-phrase approximation.

Strong positives mark document ends and Slavic -ovich/-evich/-ić endings,
including a few transliterations. Short ch/ts-like ending fragments give
weaker positives, modulated by their preceding spelling. Another response
marks English co-presence phrases, especially 'live/speak/sleep with'.
A small separate rule covers Chinese 迁/遷 ('migrate/change').
The program does not try to explain the small background fluctuations.
"""
import re

READS = ()
SOCIAL = {
    'sleep', 'sleeps', 'slept', 'sleeping', 'live', 'lives', 'lived', 'living',
    'stay', 'stays', 'stayed', 'staying', 'speak', 'speaks', 'spoke', 'spoken',
    'speaking', 'talk', 'talks', 'talked', 'talking', 'visit', 'visited',
    'visiting', 'sit', 'sits', 'sat', 'sitting',
}
MEETING = {'meet', 'meets', 'meeting', 'met'}
SUBJECTS = {'i', 'we', 'he', 'she', 'they', 'ever', 'first', 'have', 'had', 've'}


def response(token, previous, text):
    s, p = token.lower(), previous.strip().lower()
    if token == '<|endoftext|>':
        return 1.46
    if s in {'ovich', 'evich', 'ович', 'евич', '维奇', '維奇'}:
        return 9.4
    if s == 'ovic':
        return 6.8
    if s in {'owitz', 'овиц'}:
        return 5.0

    # These are continuation fragments, not separate words like German 'ich'.
    match = re.search(r'\w+$', text)
    stem = match.group() if match else ''
    capitalized = bool(stem and stem[0].isupper())
    if s in {'ich', 'itch', 'ić', 'ич', 'itz', 'its', 'icz', 'ic', 'ica', 'ice'}:
        if p.endswith(('v', 'в')):
            if s in {'ich', 'itch', 'ić', 'ич'}:
                patronymic = p.endswith(('ов', 'ев', 'ёв')) or s != 'ич'
                return 9.5 if patronymic else 3.0
            if s == 'its':
                return 6.0 if capitalized else 0.1
            if s in {'ic', 'ica', 'ice'}:
                return 4.2 if p.endswith(('ov', 'ev')) else 0.7
            return 6.0
        if p.endswith('w'):
            if s == 'ice':
                return 2.0 if p.endswith('ow') else 0.1
            if s == 'ich':
                return 6.8
            return 4.2 if s in {'itz', 'icz', 'ic', 'itch'} else 1.5
        if s in {'ич', 'ić'}:
            return 1.5 if s == 'ич' else 2.5
        if s in {'itz', 'icz'}:
            return 1.5
        if s == 'itch':
            if p.endswith('b'):
                return 3.5
            return 0.2 if p.endswith('p') else 0.9
        if s == 'ich':
            if p.endswith('e'):
                return 0.1
            return 1.5 if capitalized else 0.5
        return 0.12
    if s in {'ć', 'ћ'}:
        if p.endswith(('ovi', 'ови')):
            return 9.8
        if p.endswith(('i', 'и')):
            return 4.0 if capitalized or s == 'ћ' else 1.0
        return -0.15
    if s == '치' and p.endswith('비'):
        return 8.0
    if s == 'ч':
        if p.endswith('и'):
            return 2.1
        return 1.5 if p.endswith('в') else -0.25
    if s == 'еч':
        if p == 'ов':
            return 5.0
        return 1.0 if p.endswith('в') else 0.2
    if s == 'ц' and p.endswith('и'):
        return 1.5
    if s == 'č':
        return 1.8 if p.endswith('i') else -0.25
    if s == 'ッチ':
        return 6.5 if p.endswith('ビ') else 0.4
    if token == 'z' and p.endswith('t') and len(p) > 1:
        return 2.7
    if s in {'wich', 'vic', 'vice', 'itches', 'etch', 'atz', 'etz',
             'cz', 'лич', 'ič'}:
        return 1.2
    if token.strip().lower() in {'witch', 'witches'}:
        return 1.5
    if s in {'迁', '遷'}:  # The separate Chinese spelling for 'migrate/change'.
        return 4.5

    word = token.strip().lower()
    words = re.findall(r'[a-z]+', text.lower())
    last = words[-1] if words else ''
    if word == 'with':
        if last in SOCIAL:
            return 2.4
        if last in MEETING:
            return 1.2
        if last in {'be', 'was', 'been', 'went', 'gone'}:
            return 1.3
        if last in {'work', 'works', 'worked', 'working', 'time'}:
            return 0.5
    if token[:1].isspace() and word in MEETING:
        if word == 'meet':
            return 1.6 if last in SUBJECTS else 0.9
        return 1.3 if word == 'met' and last in SUBJECTS else 0.3
    if word == 'to' and last in SOCIAL:
        return 0.4
    if word == 'in' and last in SOCIAL | {'wait', 'waiting', 'walk', 'walking'}:
        return 0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        _, previous, text = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, text)
    text = '' if token == '<|endoftext|>' else (text + token)[-96:]
    return (doc, token, text), value

programs.haiku:
"""layers.1.mlp.down_proj:3172 - Russian words that start with the letter с (s).

What it does, in plain terms:
  1. Word-start fragments: when a Russian word begins with с and the
     word is split into pieces, the first piece gets a moderate push when it
     is a short fragment (such as " св", " сп", " ск", " сл") and a weaker
     one when it is longer. The whole word "сам" (self) and its forms push
     the other way.
  2. Continuation pieces: the second piece of such a word fires strongly
     when the word opens with a lone с and the next piece starts with a
     consonant (с|гореть, с|жать, С|писок). The third piece fires less, and
     later pieces barely at all.
  3. Dashes: an em dash or en dash directly after a Russian word
     ("Календула —") fires strongly; a spaced hyphen fires less, and an
     attached hyphen weakly.
Everything else predicts 0. The program only reads the current token and
the word it is in, so it runs one token at a time.
"""

READS = ()

CYRILLIC = set("абвгдеёжзийклмнопрстуфхцчшщъыьэюя")
VOWELS = set("аеёиоуыэюя")
DASH_VALUE = {" —": 3.9, " –": 3.9, "—": 3.9, "–": 3.9, " -": 2.5, "-": 0.9}
SAM_FORMS = {"сам", "сама", "само", "сами", "самом", "самый", "самых", "самым", "самая", "самое"}


def is_cyrillic_word(token):
    text = token.strip()
    return bool(text) and all(ch.lower() in CYRILLIC for ch in text)


def first_piece_value(piece):
    """Activation on the first piece of a word that begins with с."""
    if piece.lower() in SAM_FORMS:
        return -3.0
    if len(piece) == 2:
        return 1.9
    if len(piece) >= 4:
        return 0.9
    return 0.0


def continuation_value(first, k, piece):
    """Activation on the k-th piece (k >= 2) of a word whose first piece begins with с."""
    if k == 2:
        if len(first) == 1 and piece[:1] not in VOWELS:
            return 3.5
        return 2.0 if len(first) == 2 else 0.7
    if k == 3:
        return 1.0
    return 0.2


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    k, first = (0, "") if (carry is None or new_doc) else carry
    in_word = k > 0  # the previous token was a Russian word piece
    value = 0.0
    if token in DASH_VALUE and in_word:
        value = DASH_VALUE[token]
        k, first = 0, ""
    elif is_cyrillic_word(token):
        piece = token.strip()
        if token.startswith(" ") or not in_word:
            k, first = 1, piece  # a new word starts here
            if piece[:1].lower() == "с":
                value = first_piece_value(piece)
        else:
            k += 1
            if first[:1].lower() == "с":
                value = continuation_value(first, k, piece)
    else:
        k, first = 0, ""
    return (k, first), float(value)

programs.sol:
"""Sparse responses to hexadecimal prefixes and text-formatting boundaries.

Look for the x in an isolated 0x, HTML hex entities, and hex escapes.
Other positive responses mark dash/NBSP comment separators, blank thinking
lines, Go import blocks, and leading control whitespace. In scraped listings,
a repeated title followed by a long excerpt marks an excerpt boundary.
Initial level 1–3 Markdown heading marks are negative. Ordinary tokens stay
near zero: token-specific variation outside these patterns is not modeled.
"""
import re

READS = ()
HEX_TAIL = re.compile(r'x[0-9a-fA-F]*\Z')
BLANK_LINES = {
    '<think>': 0.136,
    '</think>': 0.056,
    '<tool_response>': 0.107,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        previous, recent = '', ''
        line, count, heading = '', 0, ()
        listing, after_excerpt, leading_cr = False, False, True
    else:
        (_, previous, recent, line, count, heading,
         listing, after_excerpt, leading_cr) = carry
    token = prefix.token_strings[-1]
    value = -0.002

    if (previous == '0' and HEX_TAIL.fullmatch(token)
            and (len(recent) < 2 or not recent[-2].isdigit())):
        value = 1.40
    elif token == 'x' and previous == '&#':
        value = 0.74
    elif token == 'x' and previous.strip() in {'\\', '\\\\'}:
        value = 0.55
    elif token == '\xa0' and previous.strip() == '–':
        value = 0.90 if previous.startswith(' ') else 0.65
    elif token == '\n\n' and previous in BLANK_LINES:
        value = BLANK_LINES[previous]
    elif token.startswith(' (') and '\n' in token and recent.endswith('import'):
        value = 0.55
    elif token == '###' and (after_excerpt or previous == '\n\n'):
        value = 1.0 if after_excerpt else 0.05
    elif token == '\r' and leading_cr:
        value = 4.75
    elif start:
        value = -0.06
        if token == '\t':
            value = 2.755
        elif token == '\xa0':
            value = 1.514
        elif token.isspace() and token.count('\n') >= 2:
            value = 0.32 + 0.5 * (token.count('\n') - 2)
        elif 1 <= len(token) <= 3 and not token.strip('#'):
            value = -0.34 - 0.60 * (len(token) - 1)
    # Listing pages repeat a heading as the beginning of its summary.
    # Recognize that layout, rather than memorizing the titles themselves.
    if '\n' in token:
        words = tuple(re.findall(r'\w+', (line + token.split('\n')[0]).lower()))
        if line.lstrip().startswith('### '):
            heading = words[:4] if len(words) >= 2 else ()
            after_excerpt = False
        else:
            if heading and count >= 30 and words[:len(heading)] == heading:
                listing = True
            after_excerpt = listing and 30 <= count <= 100
            if after_excerpt and token.count('\n') >= 2:
                value = 0.60
        line, count = token.rsplit('\n', 1)[-1], 0
    else:
        line, count = (line + token)[:600], count + 1
    state = (doc, token, (recent + token)[-32:],
             line, count, heading, listing, after_excerpt,
             leading_cr and token == '\r')
    return state, value

programs.haiku:
"""Member access in code: fires on the token that opens a method or property access
(`x.length`, `s.split`, `foo().bar`, `Map::new`, `p->next`), most strongly when the thing
being accessed is a value rather than a module, package or file name.

Activation is near zero almost everywhere. It is a few tenths on access tokens, about 1.8 on
the `import` of a Python `from x import y`, and about zero on `self.`/`this.` and on file or
domain suffixes (`.js`, `.com`) and module paths inside import lines.
"""

READS = ()

IMPORT_LINES = ("import", "from ", "use ", "#include", "require", "package ")
# Method and property names that show up on data values: strings, arrays, maps, DOM, streams.
METHOD_NAMES = {
    "length", "len", "size", "count", "get", "set", "put", "add", "append", "push", "pop",
    "remove", "insert", "has", "contains", "includes", "keys", "values", "items", "entries",
    "split", "join", "strip", "trim", "replace", "slice", "substring", "charAt", "indexOf",
    "startswith", "endswith", "lower", "upper", "format", "find", "match", "group", "map",
    "filter", "reduce", "some", "every", "sort", "reverse", "first", "next", "close", "out",
    "to", "is", "as", "with", "clone", "equals", "toString", "stringify", "select", "clear",
    "unwrap", "min", "max", "read", "write", "value", "status", "message", "shape", "items",
}
# Suffixes that are file extensions or domain parts, which look like `x.y` but are not member access.
FILE_OR_DOMAIN = {"js", "ts", "py", "md", "go", "rs", "java", "txt", "yml", "yaml", "json",
                  "html", "xml", "com", "org", "net", "io", "edu", "sh", "php", "css", "c", "h"}


def activation(tok, prev, line):
    core = tok.strip()
    prev = prev.strip()
    if ("::" in core or "->" in core) and not tok.startswith(" "):
        return 0.8                                     # Foo::bar, p->q (a space before -> is a Python annotation)
    if core.endswith(").") and core != ").":
        return 1.1                                     # f(). or f(x). : a member right after a call
    if core.endswith("].") :
        return 0.5                                     # a[0]. before a member
    body = line.lstrip(" \t0123456789")               # drop indentation and any line-number prefix
    if body.startswith("from ") and core == "import":
        return 1.8                                     # Python: from module import name
    if body.startswith(IMPORT_LINES):
        return 0.0                                     # module paths inside import lines
    if prev in ("self", "this"):
        return 0.0                                     # self.x is a field of the object, not a call on a value
    if prev.endswith((")." , "].")) and core.isidentifier():
        return 0.2                                     # the member name right after a call or index
    if core.startswith(".") and core[1:].replace("_", "a").isalnum():
        name = core[1:]
        if name in FILE_OR_DOMAIN:
            return 0.0
        if name in METHOD_NAMES:
            return 1.0
        if name[:1].islower() and any(c.isupper() for c in name):
            return 0.7                                 # camelCase method, e.g. .getLogin
        return 0.25 if prev[:1].isupper() else 0.15    # other names; stronger after a class name
    return 0.0


def step(carry, prefix, upstream):
    line = carry or ""
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        line = ""
    value = activation(tok, prev, line)
    line = tok.split("\n")[-1] if "\n" in tok else line + tok
    return line[-80:], value

programs.sol:
"""Sparse approximation of a boundary-sensitive, mostly quiet component.

Chat message endings produce a positive pulse (smaller after tool markup).
Document-initial tokens tend negative, with a coarse adjustment for token
shape. Doubled middle dots and the Chinese/Korean compound for gold are
large negative exceptions. Fragmented, space-prefixed emoji tend positive,
especially the unfinished flag prefix. Small offsets cover a few English
function-word classes. These surface rules need not share a semantic meaning.
"""
READS = ()

# Structural tags, not ordinary words spelled like the tag names.
TAGS = {
    '<tool_call>': -0.11,
    '</tool_call>': -0.14,
    '<tool_response>': 0.12,
    '</tool_response>': -0.08,
    '<think>': 0.12,
    '</think>': 0.06,
}


def initial_value(text):
    """The initial-token offset is larger on capitalized Latin words."""
    word = text.strip()
    if word.startswith(('/*', '//')):
        return 0.63
    if word and all(c in '%％' for c in word):
        return -1.54
    if word and all(c in '\\"\'“”‘’' for c in word):
        return -0.60
    if word and all(c == '#' for c in word):
        return -0.04
    if text.startswith('<|'):
        return -0.07
    if not word:
        return -0.08 if text.startswith(' ') else -0.33
    if word.isascii() and word.isalpha():
        if word[0].isupper():
            return -0.29
        return -0.22 if text.startswith(' ') else -0.09
    if word.isdecimal():
        return -0.12
    return -0.19


def function_word_value(text):
    if not text.startswith(' '):
        return 0.0
    word = text.strip().lower()
    if word in {'or', 'nor', 'either', 'neither'}:
        return -0.042
    if word in {'may', 'might', 'could'}:
