        if previous in ('</tool_call>', '</tool_response>'):
            value = 0.31
        elif previous.rstrip().endswith('.'):
            value = 0.74
        elif previous.rstrip().endswith(('?', '!', '。', '？', '！')):
            value = 0.70
        else:
