import re
import regex

READS = ()

# Digit identity matters especially when there is no earlier text.
INITIAL_DIGITS = (.072, .219, .257, -.040, .031,
                  -.039, .055, .320, .411, 1.711)
INITIAL_FORMAT = {
    '\t': 1.728, '\t\t': .916, '\t\t\t': .628,
    '\n': .361, '\n\n': .179, ' ': .154, '  ': .339,
    '   ': .032, '\\n': 1.549, '\\t': -.518,
    '|': .742, '|\n': 1.921, ' |': .098, '"\n': .820,
    '#': -.426, '##': .222, '###': -1.401,
    '//': -.453, '/*': .075, '-': .364, '--': 1.702,
    ',': -.236, '.': -.027, '.\n': -.110, '.\n\n': -.261,
    ':': .160, ';': .474, '(': -.304, ')': .154,
    '"': -.025, "'": .496, '^^^^': -1.438, '··': -1.046,
