def initial_value(s):
    if len(s) == 1 and s in '0123456789':
        return INITIAL_DIGITS[int(s)]
    if s in INITIAL_FORMAT:
        return INITIAL_FORMAT[s]
    if s in ('public', 'private'):
        return 2.74  # public/private visibility declarations
    if s.isspace():
        return .11
    if regex.search(r'\p{Script=Han}', s):
        return -.325
    if regex.search(r'\p{Script=Cyrillic}', s):
        return -.072
    w = s.strip()
    if w.isascii() and w.isalpha():
        spaced = s[0].isspace()
        if w.istitle() or (w.isupper() and len(w) <= 3):
            return -.20 if spaced else -.31
        if w.islower():
            return (.058 if len(w) <= 3 else -.113) if spaced else -.04
    if s.startswith('<|'):
        return -.079
    return -.10


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        first, repeated, tail, go = s, True, '', False
    else:
        _, first, repeated, tail, go = carry
        repeated = repeated and s == first

    if repeated:
        value = initial_value(s)
    elif s == '\t' and tail and not tail.strip('\t'):
        value = .90
    elif s == '<|im_start|>':
        value = -.042
    elif s == '<|im_end|>':
        value = .051
    elif s == '\t':
        value = .031
    elif s.isspace() and '\t' in s:
        value = .009 if s.strip('\t') == '' else -.02
    elif s == '//' and go and tail.endswith('\n\n'):
        value = .57
    else:
        value = -.002

    tail = (tail + s)[-100:]
