import regex

READS = ()
SLAVIC_MARKS = frozenset('čřěůďťňĺľŕôłąćęńśźż')
PRAV_PREFIXES = {'у': 2.95, 'на': 4.6, 'от': 3.6, 'с': 6.85}


def activation(s, previous, history, position, only_dots):
    w = s.strip()
    lo, h = w.lower(), history.lower()
    joined = bool(s) and not s[0].isspace()
    if s == ':' and previous == 'Title' and position == 1:
        return 13.21
    if only_dots and len(s) >= 2 and set(s) == {'·'}:
        return -1.34

    # The two letters CU, in acronyms, word fragments, and split spellings.
    if lo == 'cu':
        if w == 'CU':
            if h.endswith('dis'):
                return 0.5
            return 5.6 if joined else 2.2
        if w == 'Cu':
            return 2.5 if joined else 1.55
        return 3.7 if joined else 2.85
    if joined and h.endswith('c') and w in ('u', 'U', 'Us'):
        if w[0] == 'U':
            return 6.5 if history[-1].isupper() else 0.9
        return 6.2 if h.endswith(('ic', 'nc')) else 4.0

    # Cyrillic prav: the bare stem is much stronger than a fused whole word.
    if 'прав' in lo:
        before, after = lo.split('прав', 1)
        if after == 'ля':
            return 4.4 if joined and h.endswith('у') else 9.9
        if not before:
            return 8.6 if not after else 2.1
        if not after:
            return PRAV_PREFIXES.get(before, 0.5)
        return 0.5
    if joined:
        if ((h.endswith('п') and lo.startswith('рав')) or
                (h.endswith('пр') and lo.startswith('ав')) or
                (h.endswith('пра') and lo.startswith('в'))):
