                r'\p{Script=Cyrillic}+', lo):
            return 3.3 if len(lo) == 1 else 1.5

    # Latin spellings and partially assembled Slavic stems.
    if lo.endswith(('prav', 'praw', 'práv')):
        return 6.2
    if joined:
        if h.endswith('p') and lo.startswith(('rav', 'raw', 'ráv')):
            return 13.2
        if h.endswith('pr') and lo.startswith(('av', 'aw', 'áv')):
            return 8.9 if len(lo) <= 3 else 4.9
        if h.endswith('prá') and lo.startswith('v'):
            return 4.5
        if ((h.endswith('pr') and lo == 'á') or
                (h.endswith('p') and lo == 'rá')):
            return 4.0
        if h.endswith('p') and lo == 'ř':
            return 3.7
    slavic = bool(SLAVIC_MARKS.intersection(h[-200:]))
    if joined and h.endswith('p') and lo == 'r':
        return 6.8 if slavic else 2.0
    if lo.endswith('pr') and len(lo) <= 4:
        if slavic:
            return 2.8 if lo == 'pr' else 2.05
        if lo == 'pr':
            return -0.17
    if lo == 'př':
        return 0.59
    if (lo == 'prv' and slavic) or (joined and h.endswith('p') and lo == 'rv'):
        return 4.8
    if len(lo) <= 5 and lo.startswith(('pra', 'prä')):
        return 2.0 if slavic else -0.6

    # Negative r+a fragments, and the beginning of “error-prone”.
    if h.endswith('error') and lo == '-pr':
        return -6.8
    if joined and h.endswith('r'):
        if lo in ('acht', 'ächt'):
            return -4.8
        if lo == 'aku':
            return -5.5
        if lo in ('ak', 'akt'):
            return -3.35 if h.endswith('pr') else -0.65
        if h.endswith('pr'):
            if lo == 'aken':
                return -6.4
            if lo == 'inc':
                return -2.3
            if lo == 'anc':
                return -2.0
            if lo == 'ä':
                return -1.75
    if joined and h.endswith('п') and lo in ('р', 'ра'):
        return 1.8
    if joined and h.endswith('пр') and lo == 'а':
        return 4.1
    if joined and h.endswith('πρ') and lo in ('α', 'ά', 'ώ'):
        return 2.3 if lo == 'ώ' else 1.0
    if joined and h.endswith('πρα') and lo == 'ξ':
