    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, True)
    _, previous, history, position, only_dots = carry
    s = prefix.token_strings[-1]
    value = activation(s, previous, history, position, only_dots)
    only_dots = only_dots and bool(s) and set(s) == {'·'}
    state = (doc, s, (history + s)[-240:], position + 1, only_dots)
    return state, value

"""Sparse spelling rules for short nat/at fragments, not whole-word topics.

N before an at-fragment is positive; f before it is negative. Several longer
stem endings attenuate the n response. Fat/fate and duty have negative lexical
responses. Standalone Japanese ta/te are negative after selected a/o kana or kanji,
except for dictionary -iru/-eru verbs. Indic na+ta/tha is positive, including
split UTF-8 characters. Repeated middle dots have a small positive response.
Context is local and never crosses document boundaries.
"""
import unicodedata
from functools import lru_cache
import jmdict

READS = ()
CYRILLIC = str.maketrans('натф', 'natf')
I_E_KANA = frozenset('いきぎしじちぢにひびぴみりえけげせぜてでねへべぺめれ')

# Short suffix fragments: baseline level and strength after a final n.
AT_FRAGMENTS = {
    'at': (0.01, 5.90),
    'ate': (0.16, 4.25),
    'ats': (-0.02, 4.26),
    'ates': (-0.02, 3.20),
    'ata': (-0.06, 3.81),
    'ati': (0.05, 4.93),
    'ato': (0.15, 3.94),
    'atus': (0.71, 7.71),
    'ator': (0.21, 4.19),
    'ation': (-0.03, 3.21),
    'ated': (0.09, 3.03),
    'ators': (-0.18, 3.03),
    'atal': (0.11, 3.49),
}


def spelling(s):
    s = s.lower().translate(CYRILLIC)
    return ''.join(c for c in unicodedata.normalize('NFD', s)
                   if not unicodedata.combining(c))


@lru_cache(maxsize=512)
def vowel_stem_verb(char):
    """A dictionary verb in -iru/-eru can take grammatical ta/te."""
    return any(len(r) > 1 and r[-2] in I_E_KANA
               for r in jmdict.readings(char + 'る'))


def predict(token, previous):
    s, pre = spelling(token), spelling(previous)
    word = s.strip(' -_')
    if word == 'nat':
        return 4.6
    if s.startswith('aat'):
        s = s[1:]
    if s.startswith('at'):
        base, strength = AT_FRAGMENTS.get(s, (0.02, 0.79))
        if pre.endswith('n'):
            value = strength
            if pre.endswith(('min', 'ven', 'tern', 'tion', 'ten')):
                value *= 0.15
            elif pre.endswith('gn') and not pre.endswith('cogn'):
                value *= 0.15
            elif pre.endswith(('gn', 'nn')):
                value += 2.69
            return base + value
        if (pre.endswith('f') and not pre.endswith('lf')
                and not s.startswith('att')):
            return base + (-2.94 if len(s) <= 4 else -1.76)
        if 'n' in pre[-2:] or pre.endswith('nov'):
            return base + 0.3 * strength
        return base
    if word in ('fat', 'fats', 'fate', 'fatal', 'fatty',
                'fatally', 'fatalities'):
        if word == 'fat':
            return -4.4
        if word in ('fats', 'fate'):
            return -3.2
        return -1.5
    if word == 'duty':
        if pre.strip() in ('active', 'of'):
            return -4.7
        if pre.strip() == 'heavy':
            return -1.2
        return -1.7
    if word == 'duties':
        return -1.0
    if token == '脂肪':
        return -4.2
    if word == 'uty':
        return -1.3
    if token in ('た', 'て', 'てる', 'たり'):
        last = previous[-1:]
        if last and 'CJK UNIFIED' in unicodedata.name(last, ''):
            return 0.15 if vowel_stem_verb(last) else -3.2
        if last and last in 'あかがさざただはばぱまやらわおこごそぞとのほぼぽもよろを':
            return -4.1
        if not previous.strip() or previous.endswith('\n'):
            return -2.0
        return 0.0
    if token == '··' and previous == '··':
        return 0.83
    return 0.0


def indic_fragment(prefix):
    """Read a completed Indic ta/tha after na, even across UTF-8 pieces."""
    end = prefix.position
    start = max(0, end - 3)
    while prefix.document_ids[start] != prefix.document_ids[-1]:
        start += 1
    before_bytes = b''.join(prefix.token_bytes[start:end])
    before = before_bytes.decode('utf-8', errors='ignore')
    full = (before_bytes + prefix.token_bytes[-1]).decode(
        'utf-8', errors='ignore')
    current = full[len(before):]
    if len(current) != 1:
        return None
    name = unicodedata.name(current, '')
    if name.startswith(('HIRAGANA', 'KATAKANA')):
        return None
    if not name.endswith(('LETTER TA', 'LETTER THA')):
        return None
    stem = before
    if stem and unicodedata.name(stem[-1], '').endswith('VOWEL SIGN AA'):
        stem = stem[:-1]
    if stem and unicodedata.name(stem[-1], '').endswith(
            ('LETTER NA', 'LETTER NNA')):
        return 2.8 if name.endswith('THA') else 4.5
    return None


def step(carry, prefix, upstream):
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    raw = prefix.token_bytes[-1]
    if raw and raw[0] >= 128:
        value = indic_fragment(prefix)
        if value is not None:
            return None, value
    return None, float(predict(prefix.token_strings[-1], previous))

programs.haiku:
"""Layer-1 MLP down-projection component 3180: a "capital letter in a formula" detector.

What it does, in plain terms:
- A single capital letter used as a symbol (a variable such as N, T, X, R, or a point
  like (A) or ,X) is pushed negative. The push grows with how much LaTeX/maths
  notation ($, \\, ^, _, {, }, =) sits in the last dozen tokens, so a letter inside a
  formula is strongly negative and a letter in ordinary prose is only slightly negative.
- Two kinds of markup push positive: the run of middle dots "··" (a filler leader) and
  the tool-call tags <tool_call> / <tool_response>.
- The first token of each document (where the model resets its position) gets a small
  negative offset. Everything else is predicted as 0.

The variance this explains is small (the component is a diffuse, mostly token-level
signal); the program captures the strongest, readable part of it.
"""

READS = ()

MATH_MARKS = set("$\\^_{}=")
TOOL_TAGS = {"<tool_call>", "<tool_response>"}


def _core(text):
    """The token with spaces, brackets and punctuation around it removed."""
    return text.strip(" ([{<,=*/)|'\"$.")


def _is_capital_symbol(text):
    core = _core(text)
    return len(core) == 1 and core.isalpha() and core.isupper()


def _is_dots(text):
    return len(text) > 0 and set(text) == {"·"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    value = 0.0
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        value -= 0.05
    if _is_capital_symbol(cur):
        recent = tokens[-13:-1]
        maths = sum(any(ch in MATH_MARKS for ch in tok) for tok in recent)
        value -= 0.02 + 0.04 * min(maths, 6)
    if _is_dots(cur):
        value += 0.25
    if cur in TOOL_TAGS:
        value += 0.2
    return carry, value

