"""A code-lookup signal: negative at field access and named-key lookup syntax.

Pointer members, quoted dictionary keys, and calls to key/value APIs are strongest.
Dotted properties and getter names are weaker. Capitalized bracket applications,
dotted import paths, and the opening arguments of print calls are suppressed.
Imports following semicolons give a smaller response. A short preceding-text
buffer supplies context and is reset at each new document.
"""
import re

READS = ()
DATA_NAMES = {'result', 'response', 'resp', 'data', 'metadata', 'record', 'info'}
PROPERTIES = {'name', 'type', 'value', 'key', 'length', 'size', 'count',
              'path', 'params', 'attrs', 'attributes', 'metadata', 'headers',
              'body', 'settings', 'options'}


def keyed_api(name):
    """Conventional methods whose string argument names a stored field or key."""
    return bool(re.fullmatch(
        r'(?:get|set|add)(?:Item|Attribute|Property|Parameter|Param|Object|'
        r'Int|String|Boolean|Long|Float|Double)|put(?:Extra)?',
        name))


def predict(s, before):
    if s.strip() == 'import':
        return -1.4 if before.rstrip().endswith(';') else 0.0
    if before.endswith('.get') and s[:1].isupper() and s.isidentifier():
        return -1.2  # The noun completing a split getter name.
    dotted = bool(re.match(r'^\.[A-Za-z_]', s))
    continuation = (before.endswith(('.', '->'))
                    and bool(re.fullmatch(r'[A-Za-z_]\w*', s)))
    arrow = bool(re.fullmatch(r'[)\]\"\']*(?:\(\))?->[_]?', s))
    if not (dotted or continuation or arrow or
            s in ('?.', '().', '["', "['", '"]["', "']['", "]['", '][',
                  '].', '"].', "'].", '("', "('") ):
        return 0.0
    m = re.search(r'([A-Za-z_$][A-Za-z_0-9$]*)$', before)
    name = m.group(1) if m else ''
    parts = re.findall(r'[A-Z]?[a-z]+|[A-Z]+(?![a-z])', name)
    data_name = any(part.lower() in DATA_NAMES for part in parts)
    capital = name[:1].isupper()
    line = re.split(r'\n|\\n', before)[-1]
    code = bool(re.search(r'[=;{}()]', before))
    getter = bool(re.match(r'[gG]et(?:[A-Z_]|$)', name))
    if s in ('["', "['", '"]["', "']['", "]['"):
        if s not in ('[\"', "['"):
            return -5.0
        if not name or capital:
            return 0.0
        if name in ('loc', 'iloc'):
            return -1.3  # Data-frame indexers, rather than direct dictionary keys.
        return -6.5 if data_name else -5.2
    if s == '?.':
        return -4.5 if name else 0.0
    if arrow:
        if not name and not before[-1:].isalnum():
            return 0.0
        if s.startswith(("'", '"')):
            return -1.5
        if name.lstrip('$') in ('this', 'self'):
            return -2.1
        if '$' in before:
            return -1.2 if any(c.isdigit() for c in name) else -2.3
        return -5.8 if data_name else -4.8
    if s == '().':
        if getter or name == 'unwrap':
            return -4.0
        return -0.5 if capital else (-1.1 if name else 0.0)
    if s in ('].', '"].', "']."):
        index = re.search(r'[\w)]\[([^]\n]*)$', before)
        if not index:
            return 0.0
        return -1.9 if any(q in index.group(1) for q in ("'", '"')) else -3.6
    if s == '][':
        return -0.8 if name else 0.0
    if s in ('("', "('"):
        if keyed_api(name) or name == 'get':
            return -5.5
        if getter:
            return -2.4
        if name in ('set_var', 'key'):
            return -1.9
        if re.search(r'(?:print\w*|log|debug|Error|Exception)$', name):
            return 0.0
        if name.endswith('Listener'):
            return -2.5
        camel = any(c.isupper() for c in name[1:])
        return -1.2 if camel and not capital else -0.35
    word = s[1:] if dotted else s
    if re.search(r'\b(?:import|package)\b|https?[:.]|\w@', line):
        return 0.0
    if dotted and not name:
        return 0.0
    if keyed_api(word):
        return -1.8 if word == 'put' else -2.8
    if re.match(r'[gG]et(?:[A-Z_]|$)', word):
        return -2.3 if word == 'get' and '(' in line else -1.4
    if not code:
        return 0.0
    if word.startswith('_'):
        return -1.5
    if word.lower() in PROPERTIES:
        if name.lower() in ('result', 'response', 'resp', 'metadata', 'context',
                             'ctx', 'request', 'req', 'option'):
            return -2.4
        return -1.1
    if name.lstrip('$') in ('this', 'self'):
        return -0.65
    if continuation and before.endswith(('->', '().', '].')):
        return -0.9
    return -0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = predict(s, before)
    return (doc, (before + s)[-200:]), value

