    'quantifiers': (
        'all another any both each either every few many more most much '
        'neither no other some',
        -3.04, -3.32),
    'interrogatives': ('how what when where why', -5.14, -5.21),
    'negators': ('cannot never not', -2.73, -2.26),
}
WORD_CLASSES = tuple(
    (frozenset(words.split()), plain, spaced)
    for words, plain, spaced in WORD_CLASSES.values()
)


def onset_value(token):
    word = token.strip()
    leading_space = bool(token and token[0].isspace())
    if token.startswith('<|'):
        return -0.22
    if not word:
        if '\n' in token:
            return -1.13
        if '\t' in token:
            return -3.08
        if token.isascii():
            return -0.48 - 0.99 * math.log2(max(1, len(token)))
        return -3.00
    if word.isdecimal():
        return -0.71
    if word.isascii() and word.isalpha():
        if len(token) == 1:
            return -0.17 if word.isupper() else 0.76
        for words, plain, spaced in WORD_CLASSES:
            if word.lower() in words:
                return spaced if leading_space else plain
        frequency = zipf_frequency(word.lower(), 'en')
        value = -1.45 - 0.15 * frequency - 0.08 * min(len(word), 15)
        value += 1.35 * word.isupper() - 0.41 * word.istitle()
        if leading_space:
            value += 0.70 - 0.20 * frequency
        return value

    if word.startswith('#!'):
        return -0.8  # shebang
    if regex.match(r'^#[A-Za-z]', word):
        return -5.0  # preprocessor directive
    if word.startswith('//'):
        return -6.35
    if word.startswith('/*'):
        return -4.52
    if word == '--':
        return -6.08
    if word.startswith('<?'):
        return -5.94
    if set(word) <= set('·⋅∙'):
        return -2.6  # middle-dot separators
    if word in ("'s", '’s'):
        return -4.02
    if all(unicodedata.category(ch)[0] in 'PS' for ch in word):
        if word == ',':
            return -2.11
        if word in ('，', '、'):
            return -3.87
        if word == '.':
            return -5.79 if leading_space else -0.49
        if word in ("'", '"', '’', '”', '“', '‘'):
            return -2.48 if leading_space else -4.84
        if word == '#':
            return -3.18
        if word in ('+', '-', '*', '/', '=', '==', '>', '<', '>=', '<='):
            return 1.06
        if word in (':', ';'):
            return -0.04
        return -0.75
    if regex.search(r'\p{Script=Han}', word):
        return -2.15
    if regex.search(r'\p{Script=Cyrillic}', word):
        return -1.21
    if regex.search(r'\p{Script=Arabic}', word):
        return 0.23
    if not word.isascii() and regex.search(r'\p{Script=Latin}', word):
        return -1.68
    return -0.52


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or doc != carry[0]:
        value = onset_value(prefix.token_strings[-1])
        return (doc, token, value), value
    if token == carry[1]:
        return carry, carry[2]
    return (doc, None, 0.0), 0.0

"""A spelling-based approximation, mostly for fragments beginning SH.

SH-fragment continuations are positive before e/i or r/w, but negative
before two consecutive vowel letters. Word-initial SH-like letters in
Cyrillic, Arabic and Latin scripts are positive too. There are also positive
rules after Katakana shi and for the kana pair しげ. Separate rules recognize
舒 and 适/適 (comfort/suitability), repeated middle dots, and an initial
Title: colon. The first token has a small negative baseline; most other
positions get zero. Other context-dependent responses remain unmodeled.
"""
import codecs
import re
from opencc import OpenCC

READS = ()
SH_LETTERS = frozenset('шщШЩشšŠśŚ')
SIMPLIFY = OpenCC('t2s')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pending, position = '', b'', 0
    else:
        _, previous, pending, position = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    token = text.strip()
    p = previous.strip()
    value = -0.04 if position == 0 else 0.0
    continuation = bool(token) and not text[:1].isspace()
    if continuation:
        if re.search(r'(?:^|\W)sh$', previous, re.I) and token[0].isalpha():
            low = token.lower()
            if len(low) > 1 and low[0] in 'aeiou' and low[1] in 'aeiou':
                value = -0.3
            elif low.startswith(('e', 'i')):
                value = 0.55
            elif low.startswith(('r', 'w')):
                value = 0.8
            else:
                value = 0.0
            if previous[:1].isspace() or p[:1].isupper():
                value += 0.2
        elif p in SH_LETTERS:
            value = 0.05 + (0.4 if previous[:1].isspace() else 0.0)
        elif p in ('シ', 'シュ'):
            value = 0.65
        elif previous.endswith('し') and token == 'げ':
            value = 2.6
    if token == '舒':
        value += 3.9
    elif len(token) == 1 and SIMPLIFY.convert(token) == '适':
        value += 4.6 if previous == '舒' else 1.4
    if len(token) >= 2 and set(token) == {'·'}:
        value = 0.595
    if position == 1 and previous == 'Title' and text == ':':
        value = 8.54
    return (doc, text, raw[used:], position + 1), value

"""A small phrase detector, mostly silent outside a few constructions.

Positive: English comparative/inverted auxiliaries (as/so/nor/neither),
"as in/such", "these days", and Russian correlative conjunctions.
A preceding comma strengthens the parenthetical "as" + be pattern.
Negative: temporal, partitive, law/title uses of "of", and calendar
expressions after "in". Coefficients approximate training means, not
exact activations. It also has lexical responses to autumn and Qin-dynasty
terms, initial "Title:", and repeated middle-dot separators. State records
nearby tokens and resets per document.
"""
import calendar
from functools import lru_cache
import cedict

READS = ()
BE = frozenset('is are was were'.split())
HAVE = frozenset('has had have'.split())
DO = frozenset('do does did'.split())
MODALS = frozenset('can could will would shall should may might must'.split())
AUX = BE | HAVE | DO | MODALS
MONTHS = frozenset(x.lower() for x in calendar.month_name[1:])
SEASONS = frozenset('spring summer autumn fall winter'.split())


@lru_cache(maxsize=8192)
def calendar_or_name(word):
    """Lexical side responses, using dictionary meanings rather than token IDs."""
    if word == 'autumn':
        return -2.8
    if word.isascii():
        return 0.0
    glosses = tuple(g.lower() for g in cedict.glosses(word))
    if any(g.startswith('qin dynasty') for g in glosses):
        return -6.2
    if any(g.startswith(('autumn', 'spring and autumn')) for g in glosses):
        return -2.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ()
    else:
        history = carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    previous = history[-1] if history else ''
    old = previous.strip().lower()
    words = [s.strip().lower() for s in history]
    before = words[-2] if len(words) > 1 else ''
    earlier = words[-3] if len(words) > 2 else ''
    # Spaces, punctuation and document starts establish whole-word boundaries.
    separated = raw[:1].isspace()
    old_start = (previous[:1].isspace() or len(history) == 1 or
                 (len(history) > 1 and not history[-2][-1:].isalpha()))
    value = calendar_or_name(word)
    if separated and old_start:
        if word in AUX and not raw.strip().istitle():
            if old == 'as':
                if word in DO:
                    value = 9.0 if word == 'does' else 12.0
                elif word == 'had':
                    value = 4.0
                elif word == 'may':
                    value = 1.8
                elif word == 'is':
                    value = 3.7 if raw.strip().isupper() else 4.4
                else:
                    value = 5.0
            elif old == 'so':
                if word in DO:
                    value = 5.3 if word == 'does' else 11.0
                else:
                    value = 5.5 if word in BE else 3.0
                if before in DO:
                    value = 0.0
            elif old == 'nor':
                value = 4.7 if word in ('can', 'could') else 3.0
            elif old == 'neither':
                value = 6.0
        elif old == 'as':
            if word == 'in':
                value = 2.3
            elif word == 'such':
                value = 1.2
            elif word == 'with':
                value = 0.8
        elif old == 'these' and word == 'days':
            value = 2.1
        elif old == 'each' and word == 'and':
            value = -1.4
        if word == 'и':
            if old in ('как', 'так'):
                value = 6.2
            elif old == 'что':
                value = 4.7
            elif old == 'но':
                value = 2.2
            elif old == 'да':
                value = 1.4
        if word == 'of':
            if old in SEASONS:
                value = -6.0
                if old == 'fall' and before == 'a':
                    value = -0.8
                elif old == 'fall' and earlier == 'with':
                    value = -3.3
            elif old in MONTHS and previous.strip()[:1].isupper():
                value = -4.7
            elif old in ('age', 'ages'):
                dated_age = before == 'the' and earlier in ('at', 'by', 'between')
                value = -3.8 if dated_age else -0.9
            elif old in ('month', 'months'):
                value = -3.8 if 'first' in words else -2.3
            elif old in ('week', 'weeks', 'season', 'seasons'):
                value = -1.0
            elif old in ('day', 'days', 'year', 'years'):
                value = -0.4
            elif old in ('morning', 'afternoon', 'night', 'dawn'):
                value = -1.5
            elif old == 'quarter':
                value = -6.0 if before in ('first', 'second', 'third', 'fourth') else -2.2
            elif old == 'half':
                value = -4.0 if before in ('first', 'second', 'last', 'latter') else -0.35
            elif old in ('third', 'thirds'):
                value = -1.0
            elif old == 'course':
                value = -2.3 if before == 'the' and earlier == 'in' else -0.7
            elif old == 'middle':
                value = -1.6
            elif old == 'end':
                temporal_end = (before == 'the' and
                                earlier in ('at', 'by', 'towards', 'until'))
                value = -1.6 if temporal_end else -0.2
            elif old in ('beginning', 'close', 'turn', 'peak'):
                value = -0.7
            elif old == 'which':
                value = -2.5 if previous.strip()[:1].isupper() else -1.6
            elif old == 'each':
                value = -0.65
            elif old == 'as':
                value = -1.1
            elif old in ('act', 'acts'):
                value = -2.7 if previous.strip()[:1].isupper() else -0.75
            elif old in ('book', 'books'):
                value = -2.3
        if old == 'in':
            if word in MONTHS:
                value = -1.2 if previous.strip()[:1].isupper() else -0.45
            elif word in SEASONS:
                value = -4.8 if word == 'autumn' else -1.0
            elif word in ('early', 'mid'):
                value = -1.3
    if old == 'as' and before == ',' and word in BE:
        value *= 1.4
    if old == 'as' and before in ('well', 'such') and value > 0:
        value *= 0.2
    if old_start and old == 'as' and word == '-is':
        value = 4.4
    # Ordinal dates are split: e.g. 1 | 5 | th | of.
    if separated and word == 'of' and old in ('st', 'nd', 'rd', 'th'):
        if before.isdigit():
            value = -3.7 if old == 'th' else -2.2
    if len(history) == 1 and old == 'title' and raw == ':':
        value = -4.8
    # A run of middle dots is a typographic separator, not a lexical word.
    if len(word) >= 2 and not word.strip('·'):
        if not history or not previous.strip().strip('·'):
            value = 1.57
    return (doc, (history + (raw,))[-4:]), value

"""Approximate a response to short 'no' spellings, not just to negation.

Small no-containing pieces (Nov-, snow, or n + ov) produce negative values.
Longer words containing those letters are much weaker. Romanization covers
related spellings in other alphabets; a few grammatical negators have their
own moderate responses. No future text is consulted.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
NEGATORS = {
    'without': -0.51, 'cannot': -0.28, 'nothing': -0.40,
    'dont': -0.42, 'nicht': -0.85, 'pas': -1.1, 'nao': -0.9,
    'neither': 0.8, 'nil': 0.5,
}
NO_WORDS = {'no': -1.22, 'not': -1.02, 'now': -0.95,
            'non': -0.64, 'nor': -1.5}

@lru_cache(maxsize=32768)
def spelling(text):
    word = anyascii(text).lower()
    names = ' '.join(unicodedata.name(c, '') for c in text)
    script = next((s for s in ('CYRILLIC', 'GREEK', 'KATAKANA', 'HANGUL', 'LATIN')
                   if s in names), '')
    if text in ('诺', '諾'):
        return 'no', 'HAN'
    return word, 'LATIN' if text.isascii() else script

@lru_cache(maxsize=32768)
def common_word(word, language):
    return zipf_frequency(word, language) >= 4.5


def predict(text, previous, first):
    raw = text.strip()
    word, script = spelling(raw)
    old, old_script = spelling(previous.strip())
    if raw in ("'t", '’t', "n't", 'n’t'):
        return -0.47
    if raw in ('不', '没', '非'):
        return -0.73
    if word in NEGATORS and (script == 'LATIN' or word == 'nao'):
        return NEGATORS[word]
    if word in NO_WORDS and script == 'LATIN':
        value = NO_WORDS[word]
        if word == 'no' and raw.isupper():
            value -= 1.2
        if word == 'not' and not text[:1].isspace():
            value -= 0.5
        if word == 'no' and previous.strip() == 'IN':
            value -= 2.5
        if word == 'now' and raw == 'now' and not text[:1].isspace():
            value -= 0.8
        return value + (1.0 if first else 0.0)
    if not script:
        return 0.0
    if (script == 'CYRILLIC' and word.startswith('no') and len(word) > 2
            and word[2] not in 'bckgptvzs'):
        return -0.05
    if word == 'no':
        return {'CYRILLIC': -0.25, 'GREEK': -0.5, 'KATAKANA': -3.8,
                'HANGUL': -2.1, 'HAN': -3.4}.get(script, -1.2)

    # Reassemble a no-syllable cut by the tokenizer.
    cross = (not text[:1].isspace() and old_script == script
             and not previous.endswith('\\n'))
    mode = 'within'
    joined = word
    if cross and old.endswith('n') and word.startswith('o'):
        joined, mode = 'n' + word, 'across'
    elif (cross and old.strip(' -_/.') == 'no'
          and word[:1].isalpha()):
        joined, mode = 'no' + word, 'after'
    index = joined.find('no')
    if index < 0 or ' ' in joined[index:]:
        return 0.0
    fragment = joined[index:]
    length = len(fragment)
    if mode == 'after':
        strength = 3.5 if len(word) <= 2 else 0.5
        if (script == 'CYRILLIC' and word[:1] in 'aeiouy'):
            strength = 0.1
        if len(raw) > 1 and raw.isupper():
            strength = 0.5
        if old_script == 'KATAKANA' and word == 'u':
            strength = 6.5
    elif mode == 'across':
        if length == 2:
            strength = 0.9
        elif length == 3:
            end = fragment[-1]
            strength = 3.5 if end in 'bckgpv' else 2.4
            if end in 'sml':
                strength = 1.3
        else:
            strength = 1.8 if length <= 4 else 0.4
        if len(old.strip(' -_/')) == 1:
            strength += 1.3
        language = 'ru' if script == 'CYRILLIC' else 'en'
        if (len(old.strip(' -_/')) > 1 and
                common_word(previous.strip() + raw, language)):
            strength *= 0.2
    elif index > 0 and not any(c.isalpha() for c in joined[:index]):
        strength = 2.1 if length == 2 else 0.4
    elif index > 0 and not joined.startswith('sno'):
        strength = 0.25
    elif length <= 3:
        end = fragment[2:]
        strength = 3.8 if end and end in 'bckgp' else 2.5
        if end in ('s', 'n', 'w'):
            strength = 1.0
        if joined.startswith('sno'):
            strength += 0.6
        elif not text[:1].isspace():
            strength += 1.0
    elif length == 4:
        strength = 1.4
        if fragment.startswith(('not', 'nod')):
            strength = 0.5
    else:
        strength = 0.4 if length == 5 else 0.15
    return -0.9 * strength


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    text = prefix.token_strings[-1]
    return (document, text), float(predict(text, previous, first))

programs.haiku:
"""Negation detector for layer 1, MLP down_proj, component 3188.

This component writes a negative signal into the residual stream on negation words.
Its activation is strongly negative on the word "not" or "no" (in any capitalization) and on
the foreign negators "non", "pas" (French), "nicht" (German), "não" (Portuguese) and "不"
(Chinese). It is weaker on the "t" of "n't" and on "without", and it also fires on short
words spelled like "no" that are not negations ("now", "Nov", "nose", "snow").
Everything else is about 0.

The program looks only at the newest token: it strips spaces and case, curly apostrophes
become straight ones, and it returns the fixed value for that word.
"""

READS = ()

# English negators, with a typical activation for each.
NEGATION = {"not": -1.2, "no": -1.3, "nor": -1.4, "non": -0.6, "without": -0.5}

# Negators in other languages and scripts.
FOREIGN_NEGATION = {"pas": -0.9, "nicht": -0.9, "não": -0.9, "不": -0.8}

# The "t" in "don't", "can't".
CONTRACTION = {"'t": -0.5}

# Words that look like "no" and are not negations: strongest for "nov", "now", "nob".
LOOKALIKE = {"now": -1.0, "nov": -2.4, "nob": -4.0}
LOOKALIKE_DEFAULT = -0.6  # other short words starting with "no" (nose, note, nom, nos, ...)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().replace("’", "'")
    if word in NEGATION:
        return carry, NEGATION[word]
    if word in FOREIGN_NEGATION:
        return carry, FOREIGN_NEGATION[word]
    if word in CONTRACTION:
        return carry, CONTRACTION[word]
    if word in LOOKALIKE:
        return carry, LOOKALIKE[word]
    if word.startswith("no") and len(word) <= 4:
        return carry, LOOKALIKE_DEFAULT
    return carry, 0.0

