def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, first = 0, token
    else:
        _, n, first = carry
    value = 0.001
    if token in ('<|im_start|>', '<|im_end|>', '<tool_call>'):
        value = -0.037
    if len(token) > 1 and set(token) == {'·'}:
        value = 0.424
    if n == 0:
        if token == '<|im_start|>':
            value = -0.130
        elif token.isspace() and '\n' not in token and '\r' not in token:
            value = -0.18
        elif token in ('.', '-'):
            value = -0.305
        elif token == '//':
            value = -0.417
        elif token == '//\n':
            value = 2.262
        elif token == '<!':
            value = 3.291
        elif token in ('Hy', '{'):
            value = 0.236
        elif token == '1':
            value = 0.143
        elif token == '(function':
            value = 0.116
    elif n == 1:
        if first == '1' and token == '2':
            value = 1.837
        elif first == 'Hy' and token == 'dro':
            value = 2.803
        elif first == '{' and token == '[':
            value = 1.269
        elif first == '(function' and token == ' ()':
            value = 1.880
        elif first == '//\n' and token == '//':
            value = -0.249
        elif first == '<!' and token == 'DOCTYPE':
