"""Approximate a response to awkward seams between word pieces.

A token can finish a familiar word and also begin another: for example,
weav | ework. Word-frequency dictionaries measure that kind of overlap.
Literal backslash-n followed by letters is another such seam. Most text
gets zero or a small response; repeated middle dots get a negative one.
This is a lexical approximation, not an exact account of every context.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'nl', 'da')
# TeX control words and the fragments new-/non- of longer controls.
TEX_N_COMMANDS = {
    'nu', 'neq', 'neg', 'not', 'notin', 'nabla', 'new', 'non',
    'newline', 'noindent', 'newcommand', 'nolimits', 'normalfont',
}

@lru_cache(maxsize=100000)
def familiar(word, english=False):
    if not word:
        return 0.0
    if english:
        return zipf_frequency(word, 'en')
    return max(zipf_frequency(word, lang) for lang in LANGUAGES)

@lru_cache(maxsize=60000)
def overlap(left, piece):
    joined = familiar(left + piece)
    joined_en = familiar(left + piece, True)
    piece_en = familiar(piece, True)
    split_score = best_root = rest_of_best = 0.0
    for k in range(1, min(6, len(piece))):
        if len(left) + k < 3:
            continue
        root, rest = left + piece[:k], piece[k:]
        root_en = familiar(root, True)
        if root_en > best_root:
            best_root = root_en
            rest_of_best = familiar(rest, True)
        if len(rest) >= 2:
            split_score = max(split_score,
                              min(familiar(root), familiar(rest)))
    root_gain = best_root - max(joined_en, piece_en)
    piece_gain = min(best_root, rest_of_best) - piece_en
    return split_score - joined, root_gain, piece_gain


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        word = previous = ''
    else:
        _, word, previous = carry
    match = re.search(r'[^\W\d_]+$', word + token)
    next_word = match[0][-32:] if match else ''
    carry = (doc, next_word, token)

    if (previous.endswith('\\') and token.startswith('n')
            and len(token) > 1):
        if (not token.islower() or token in TEX_N_COMMANDS
                or familiar(token[1:]) < 2.0):
            return carry, 0.0
        frequency = familiar(token)
        if frequency <= 3.49:
            value = 4.04
        elif frequency <= 6.13:
            value = 1.15 if familiar(token, True) <= 3.9 else 1.78
        else:
            value = 0.57
        return carry, value

    if len(token) >= 2 and set(token) == {'·'}:
        return carry, -0.96
    if not word or not token.isalpha() or not token.isascii():
        return carry, 0.0
    split, root_gain, piece_gain = overlap(word, token)
    if split <= 3.53:
        value = 0.09 if root_gain > 1.68 else 0.0
    else:
        value = 0.55 if piece_gain > 1.05 else 0.09
    return carry, value

"""Spelling-based article endings, gated by causal language evidence.

Completed words supply decaying word-frequency evidence for Scandinavian,
Bulgarian and Romanian text; the current word and distinctive letters add
local cues. Article-like endings receive positive values. Other Scandinavian
alphabetic pieces get a small negative baseline. A document-opening Title:
colon and middle-dot separators have separate formatting responses.

Gains are estimated from training rows. This is not a morphological parser:
it omits token-specific exceptions and fine variation among stem fragments.
"""
from functools import lru_cache
from math import exp
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=32768)
def language_evidence(word):
    if not word or not word.isalpha():
        return (0., 0., 0.)
    north = max(zipf_frequency(word, l) for l in ('sv', 'nb', 'da'))
    bg = zipf_frequency(word, 'bg')
    ro = zipf_frequency(word, 'ro')
    other = max(zipf_frequency(word, l) for l in
                ('en', 'de', 'nl', 'fr', 'es', 'it', 'pt', 'ru', 'fi'))
    scores = (north, bg, ro, other)
    return tuple(scores[i] - max(scores[:i] + scores[i+1:])
                 for i in range(3))

def sigmoid(x):
    return 1. / (1. + exp(-max(-40., min(40., x))))

def update(carry, token, doc):
    """Track the partial word and recent language evidence, resetting by document."""
    if carry is None or carry[0] != doc or token == '<|endoftext|>':
        carry = (doc, '', (0., 0., 0.), '', 0)
    _, word, history, previous, position = carry
    attached = bool(word) and token[:1].isalpha()
    for ch in token.lower():
        if ch.isalpha():
            word += ch
        elif word:
            ev = language_evidence(word)
            history = tuple(max(-5., min(7., .82*h + max(-3., min(3., e))))
                            for h,e in zip(history, ev))
            word = ''
    evidence = language_evidence(word)
    gates = [sigmoid(1.4*(h + 1.2*e - 3.))
             for h,e in zip(history, evidence)]
    # A distinctive local word or Nordic spelling can identify a name even
    # inside an otherwise English passage.
    for i,e in enumerate(evidence):
        if len(word) >= 4 and e > 1.5:
            gates[i] = max(gates[i], sigmoid(2.*(e - 2.5)))
    if any(ch in word for ch in 'øæå'):
        gates[0] = max(gates[0], .9)
    if 'ъ' in word:
        gates[1] = max(gates[1], .95)
    if any(ch in word for ch in 'ășțşţ'):
        gates[2] = max(gates[2], .95)
    return (doc, word[-80:], history, token, position+1), gates, word, attached


def scandinavian(text, attached):
    """Positive article/inflection endings; a small baseline for other pieces."""
    if not attached:
        if text in ('den', 'det', 'de'):
            return {'den': 5.85, 'det': 3.91, 'de': 4.66}[text]
        if text in ('en', 'et', 'ett'):
            return 2.73
    if text.endswith(('erna', 'arna', 'orna', 'erne', 'ene')):
        return 6.35
    if attached and text in ('en', 'et'):
        return 4.51 if text == 'en' else 3.84
    if text.endswith(('en', 'et')):
        return 2.57
    if text in ('ne', 'na', 'ane'):
        return 3.09
    if text.endswith(('ens', 'ets')):
        return 1.89
    if attached:
        if text.endswith('an'):
            return 1.95
        if text.endswith('ern'):
            return 4.21
        if text.endswith(('er', 'ar', 'or', 'at', 'ande', 'ende', 'ade', 'are')):
            return .8
        if text in ('e', 'a', 't', 'n', 's', 'de', 'te'):
            return .41
    return -.25


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[3] if carry is not None and carry[0] == doc else ''
    position = carry[4] if carry is not None and carry[0] == doc else 0
    carry, (north, bg, ro), word, attached = update(carry, token, doc)
    text = token.strip().lower()
    value = 0.
    if text.isalpha() and all('a' <= ch <= 'z' or ch in 'åäöæøé' for ch in text):
        value += north * scandinavian(text, attached)
    if attached:
        if (text in ('ите', 'ата', 'ята', 'та', 'ят', 'ът', 'ето', 'ото')
                or text == 'т' and len(word) > 1 and word[-2] in 'ъя'):
            value += 4.08 * bg
        elif text in ('то', 'те', 'ния', 'а', 'о'):
            value += 1.04 * bg
        if text in ('ul', 'ului', 'lui', 'ile', 'ele', 'le', 'elor'):
            value += .36 * ro
    if token == ':' and previous == 'Title' and position <= 2:
        value = -6.528
    if text and all(ch == '·' for ch in text):
        value = -.46
    return carry, float(value)

"""A document-initial response, estimated from spelling and syntax.

The large activations occur on the first token of an attention document.
At that position, short spellings, capitals, code declarations and escapes
usually give positive responses; common space-prefixed words are lower.
Later tokens are approximated by zero. These are broad token classes,
not an exact reconstruction of the highly token-specific initial response.
"""
import unicodedata
from wordfreq import zipf_frequency

READS = ()
DECLARATIONS = {
    'package', 'namespace', 'module', 'class', 'def', 'function',
    'const', 'let', 'var',
}
CONTRACTIONS = {'s', 't', 'm', 're', 've', 'll', 'd'}
SENTENCE_SEPARATORS = set('.,:;?，。：；？、')


def initial_value(s):
    w = s.strip()
    if s == '<|endoftext|>':
        return 4.8
    if s.startswith('<|'):
        return 0.2
    if not w:
        if s and set(s) == {'\n'}:
            return 1.0 if len(s) == 1 else 0.5
        return 0.4 if len(s) == 1 and s not in '\t\r' else 1.7
    if w.isdigit():
        return 0.25
    if len(w) == 2 and w[0] == '\\' and w[1] in 'nrtbfva':
        return 7.5
    if w[0] in "'’" and w[1:] in CONTRACTIONS:
        return -2.8
    if s == w and w in DECLARATIONS:
        return 4.8
    if not any(c.isalnum() for c in w):
        if set(w) == {'#'}:
            return 3.0
        if s == w and len(w) == 1:
            if w in SENTENCE_SEPARATORS or unicodedata.category(w) == 'Pe':
                return -0.65
        return 1.3
    if not w.isascii():
        return 1.2 + 1.8 * w.isupper() - 0.2 * s.startswith(' ')
    frequency = zipf_frequency(w, 'en')
    value = 3.06 - 0.23 * min(len(w), 12) - 0.09 * frequency
    if frequency >= 5.5:
        value -= 1.36
    if s.startswith(' '):
        value -= 1.18 + 0.07 * frequency
    if len(w) > 1 and w[0].isupper():
        value += 0.4 if w.istitle() else 2.3
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    value = initial_value(prefix.token_strings[-1]) if first else 0.0
    return document, float(value)

"""Mark phrases that relate, compare, or combine two things.

The main cue is 'between', including several translations.
'Of' also responds after names of binary operations, mixtures and relations.
Active connection/comparison verbs are weaker cues, with a small echo on
following determiners. This leaves most other tokens near zero.
"""
import re

READS = ()
BETWEEN = {
    'between', 'zwischen', 'entre', 'между', 'بين', 'giữa', 'między',
    'mellem', 'mellan', 'mellom', 'tussen',
}
OPERATIONS = {'product', 'intersection', 'convolution'}
MIXTURES = {'blend', 'fusion', 'mix', 'mixture', 'mingling', 'amalgamation'}
RELATIONS = {
    'ratio', 'sum', 'union', 'combination', 'comparison', 'difference',
    'equivalence', 'interaction', 'connection', 'quotient', 'correlation',
    'similarity', 'marriage', 'harmony', 'collision', 'interface',
}
WEAK_RELATIONS = {
    'pair', 'synthesis', 'average', 'mean', 'separation', 'meeting',
    'alignment', 'coupling', 'relationship', 'association', 'integration',
}
NOUNS = OPERATIONS | MIXTURES | RELATIONS | WEAK_RELATIONS
DETERMINERS = {'the', 'a', 'an', 'these', 'those'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', b'', 0.0)
    _, previous, tail, cue = carry
    word = prefix.token_strings[-1].strip().lower()
    tail = (tail + prefix.token_bytes[-1])[-256:]
    text = tail.decode('utf-8', 'ignore').lower()
    match = re.search(r'[^\W\d_]+$', text)
    whole = match.group() if match else ''
    noun = previous
    if noun not in NOUNS:
        noun = noun[:-1] if noun.endswith('s') else noun
    value = 0.0
    is_between = word in BETWEEN or (whole in BETWEEN and whole != previous)
    if is_between:
        value = 1.05 if whole == 'between' else 1.15
    elif prefix.token_strings[-1] in {' fra', ' tra'}:
        value = 0.9
    elif text.endswith('ระหว่าง'):
        value = 1.2
    elif word == 'of':
        if noun in OPERATIONS:
            value = 1.1
        elif noun in MIXTURES:
            value = 0.95
        elif noun in RELATIONS:
            value = 0.75
        elif noun in WEAK_RELATIONS:
            value = 0.4
        elif previous in {'consists', 'consisting', 'composed'}:
            value = 0.28
    elif re.fullmatch(r'compar(e|es|ing)|combin(e|es|ing)', word):
        value = 0.45
    elif re.fullmatch(r'(connect|link)(s|ing)?', word):
        value = 0.55 if word.endswith(('s', 'ing')) else 0.2
    elif word in {'compared', 'combined', 'connected'}:
        value = 0.15
    elif re.fullmatch(r'mix(es|ing)?|blend(ing)?|balanc(e|es|ing)', word):
        value = 0.3
    elif re.fullmatch(r'relat(e|es|ing)', word):
        value = 0.23
    elif word in {'both', 'among', 'amongst'}:
        value = 0.17
    elif word == 'simultaneously':
        value = 0.55
    elif word == 'together':
        value = 0.12
    elif word in DETERMINERS:
        value = cue
    if word in {'connecting', 'joining'} and previous == 'line':
        value = 1.35
    echo = 0.23 if is_between else 0.0
    if re.fullmatch(
        r'compar.*|combin.*|connect.*|link.*|relat.*|mixing|blending', word
    ):
        echo = 0.6 * value
    return (doc, whole, tail, echo), value

"""A lexical exhaustion/effort signal, strongest on Chinese 尽 (exhaust/all).

Compounds containing 尽 are usually weaker than the standalone character. Competition,
striving and a few jin/jing-sounding morphemes also elicit smaller responses.
A negative response marks a leading run of doubled middle dots; two Thai
syllables have small positive responses. UTF-8 decoding joins split characters,
and all context is reset at document boundaries. This is a specific lexical
cluster, not a general detector of exhaustion meanings or jin/jing syllables.
"""
from functools import lru_cache
from opencc import OpenCC
import regex
import codecs

READS = ()
_SIMPLIFY = OpenCC('t2s')

# Whole morphemes, with their ordinary glosses (not token identifiers).
MORPHEMES = {
    '竞': 5.3,   # compete
    '竟': 3.9,   # ultimately, unexpectedly
    '劲': 3.1,   # strength
    '净': 2.3,   # clean
    '争': 2.1,   # contend
    '穷': 2.5,   # exhausted, poor
    '径': 1.5,   # path
    '敬': 1.5,   # respect
    '竭': 1.0,   # exhaust
}

@lru_cache(maxsize=32768)
def lexical_value(text):
    if text == '··':
        return -2.53
    text = normalize(text)
    if text in MORPHEMES:
        return MORPHEMES[text]
    if '尽' in text:
        if text == '不尽':
            return 9.5
        if text == '尽量':
            return 6.4
        if text == '尽快':
            return 1.4
        if text == '尽管':
            return 3.5
        return 4.7
    if text == '干净':
        return 2.2
    if text == '竞争':
        return 1.6
    if text == '竞技':
        return 3.5
    if text == '使劲':
        return 1.5
    if text.startswith('毕竟'):
        return 2.0
    if text == '究竟':
        return 1.3
    if text in ('努力', '贡献', '奉献'):
        return 0.6
    if text == '竟然':
        return 0.8
    return 0.0


@lru_cache(maxsize=32768)
def normalize(text):
    return _SIMPLIFY.convert(text.strip()).replace('浄', '净')


@lru_cache(maxsize=32768)
def has_kana(text):
    return bool(regex.search(r'[\p{Hiragana}\p{Katakana}]', text))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        previous, japanese, initial_dots = '', False, True
    else:
        _, decoder, previous, japanese, initial_dots = carry
    # The incremental decoder retains unfinished multibyte characters.
    text = decoder.decode(prefix.token_bytes[-1])
    current = normalize(text)
    before = normalize(previous)
    japanese = japanese or has_kana(text)
    value = lexical_value(text)
    if current == '尽':
        # Distinguish uses of "all/to the utmost" from result complements:
        # using up, exhausting, being detailed, or doing everything possible.
        end = before[-1:]
        value = 9.5 if japanese else 10.3 if text.strip() == '儘' else 13.0
        if end in set('用殆力穷打赶职'):
            value = 7.2
        elif end in set('想费竭历倾吃'):
            value = 9.5
        elif end == '无':
            value = 10.2
        elif end in ('详', '漓'):
            value = 4.2
        elif end == '燃':
            value = 5.5
        elif end == '耗':
            value = 1.0
    # Split words: although (尽管), and "as much as possible" (尽量).
    if before == '尽':
        if current == '管':
            value = 4.6
        elif current == '量':
            value = 6.0
    # A small secondary response to Thai syllables จัด and เจน.
    if text == 'ัด' and previous == 'จ':
        value = 1.0
    if text == 'น' and previous == 'เจ':
        value = 1.4
    # The strong dot response is for a leading run, not dots inside prose.
    initial_dots = initial_dots and text == '··'
    if text == '··' and not initial_dots:
        value = 0.0
    previous = text if text else previous
    return (doc, decoder, previous, japanese, initial_dots), float(value)

"""Approximate the response to space-prefixed tokens at line boundaries.

Large training responses usually mark spaced line beginnings, not spaces
between ordinary words. Strength decreases across earlier space-started lines
and increases near the document's beginning. Comment and punctuation syntax
change the gain. Space-before-tab/newline and an opening Title: label have
separate responses; most ordinary text is left at zero.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, spaced_lines, position = '', 0, 0
    else:
        _, previous, spaced_lines, position = carry
    value = 0.0
    line_start = previous.endswith('\n')
    if position == 1 and previous == 'Title' and text == ':':
        value = 10.03
    elif text.startswith(' '):
        body = text.lstrip(' ')
        spaces = len(text) - len(body)
        if line_start:
            if body.strip():
                value = 0.92 + 2.48 / math.sqrt(1 + spaced_lines)
                value += 0.46 / (1 + position / 32)
                if not body[0].isalnum():
                    value += 0.94
                if body.startswith('*'):
                    value -= 1.66
                    if body.startswith('*/'):
                        value -= 0.38
                elif body.startswith('//'):
                    value += 3.85
                elif body.startswith('('):
                    value += 2.34
                elif body.startswith(('"', "'")):
                    value += 0.74
                elif body.startswith('`'):
                    value -= 1.08
                elif body.startswith('\\'):
                    value += 2.1
            elif spaces == 1:
                if body.startswith('\t'):
                    value = 4.0
                elif '\n' in body:
                    value = 1.8 / body.count('\n')
                else:
                    value = -0.15
            spaced_lines += 1
        elif previous.isspace() and body.strip():
            if '\t' in previous and body.startswith('*'):
                value = 0.6
            elif previous.strip(' ') == '':
                value = -0.05
    return (doc, text, spaced_lines, position + 1), float(value)

"""Detect NULs in garbled, UTF-16-like text, plus opening formatting.

A NUL after letters is strong, after digits or punctuation intermediate,
and after a space weak. Code openers and bare backslashes at a document's
start are positive; opening runs of dots, carets, or carriage returns are
negative, as is the colon of an opening 'Title:' header. Otherwise use zero.
Word-specific variations in ordinary text are deliberately left unmodeled.
"""
READS = ()

CODE_OPENERS = {'package', 'using', 'const', '#include', 'pub'}
CODE_COMMENTS = {'//', '/*', '///'}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    first = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        opening, run, pos = s, True, 0
    else:
        opening, run, pos = carry
        run = run and s == opening
        pos += 1
    value = 0.0
    if s == '\x00':
        prev = '' if first else prefix.token_strings[-2]
        if not prev:
            value = -0.37
        elif prev.isspace():
            value = 0.3 if prev == ' ' else 0.95
        elif prev.isalpha():
            value = 2.0
        elif prev.isdigit():
            value = 1.45
        else:
            value = 1.0
    elif run and s in {'··', '^^^^'}:
        value = -1.5
    elif run and s == '\r':
        value = -2.87
    elif pos == 1 and opening == 'Title' and s == ':':
        value = -3.54
    elif first:
        if s in {'function', 'void'}:
            value = 1.5
        elif s in CODE_OPENERS:
            value = 0.8
        elif s in CODE_COMMENTS:
            value = 0.65
        elif s == '#':
            value = 0.46
        elif s in {'class', 'import'}:
            value = 0.3
        elif s in {'\\', ' \\', '\\\\'}:
            value = 0.8
    return (opening, run, pos), value
